"""
Book 35: The Canterville Ghost - Complete Dataset (25 Pages, 500 Sentences, 200 Vocab)
Oscar Wilde
"""

BOOK_DATA = [{'page_no': 1, 'title': 'The Purchase of Canterville Chase', 'tr_title': 'Canterville Malikanesinin Satın Alınması', 'vocab_focus': [('minister', 'elçi, diplomat, bakan'), ('chase', 'av köşkü, malikane'), ('warning', 'uyarı, ikaz'), ('superstition', 'batıl inanç'), ('purchase', 'satın almak'), ('furniture', 'mobilya'), ('sensible', 'mantıklı, aklı başında'), ('diplomat', 'diplomat')], 'sentences': [{'id': 1, 'text': 'When Mr. Hiram B. Otis, the American Minister, bought Canterville Chase, everyone told him he was doing a foolish thing.', 'translation': "Amerikan Elçisi Bay Hiram B. Otis Canterville Köşkü'nü satın aldığında, herkes ona çok aptalca bir iş yaptığını söyledi.", 'notes': "bought Canterville Chase: Canterville Köşkü'nü satın aldı."}, {'id': 2, 'text': 'There was no doubt whatever that the ancient Tudor estate was haunted by a terrifying ancestral spirit.', 'translation': 'Eski Tudor malikanesinde korkunç bir ata ruhunun kol gezdiğine dair en ufak bir şüphe dahi yoktu.', 'notes': 'no doubt whatever: en ufak bir şüphe dahi yok.'}, {'id': 3, 'text': 'Indeed, Lord Canterville himself felt bound to mention the ghost to Mr. Otis when they discussed the terms of the sale.', 'translation': "Nitekim Lord Canterville'in bizzat kendisi, satış şartlarını görüştüklerinde hayaletten Bay Otis'e bahsetmeyi bir görev bildi.", 'notes': 'felt bound to mention: bahsetmeyi görev bildi.'}, {'id': 4, 'text': '"We have not cared to live in the place ourselves," said Lord Canterville, "since my grandaunt was frightened into convulsions."', 'translation': '"Büyük halam korkudan havale geçirdiğinden beri," dedi Lord Canterville, "orada bizzat yaşamayı hiç tercih etmedik."', 'notes': 'frightened into convulsions: korkudan havale geçirdi.'}, {'id': 5, 'text': '"The poor Duchess of Bolton was dressing for dinner when two skeleton hands were placed upon her shoulders."', 'translation': '"Zavallı Bolton Düşesi akşam yemeği için giyiniyordu ki omuzlarına iki iskelet el dokundu."', 'notes': 'skeleton hands: iskelet eller.'}, {'id': 6, 'text': '"She had a terrible nervous fit from which she never really recovered, and our family abandoned the manor."', 'translation': '"Asla tam olarak atlatamadığı korkunç bir sinir krizi geçirdi ve ailemiz malikaneyi terk etti."', 'notes': 'nervous fit: sinir krizi.'}, {'id': 7, 'text': '"I feel it my duty to tell you, Mr. Otis, that the ghost has been well known in our family for three centuries."', 'translation': '"Bay Otis, hayaletin üç yüz yıldır ailemizde çok iyi bilindiğini size söylemeyi bir vazife bilirim."', 'notes': 'feel it my duty: bunu vazife bilirim.'}, {'id': 8, 'text': '"It always makes its appearance before the death of any member of our noble lineage."', 'translation': '"Asil soyumuzun herhangi bir üyesinin vefatından önce daima kendini gösterir."', 'notes': 'makes its appearance: kendini gösterir, ortaya çıkar.'}, {'id': 9, 'text': '"Well, so does the family doctor for that matter, Lord Canterville!" the practical American minister laughed cheerfully.', 'translation': '"Eh, o bakımdan aile hekimi de aynısını yapar Lord Canterville!" diye neşeyle güldü pratik Amerikalı elçi.', 'notes': 'laughed cheerfully: neşeyle güldü.'}, {'id': 10, 'text': '"I come from a modern country where we have everything that money can buy and science can explain."', 'translation': '"Paranın satın alabileceği ve bilimin açıklayabileceği her şeye sahip olduğumuz modern bir ülkeden geliyorum."', 'notes': 'money can buy: paranın satın alabileceği.'}, {'id': 11, 'text': '"With our young fellows painting the old world red, if there were a real ghost in Europe, we would soon have it at home!"', 'translation': '"Eski dünyayı fetheden gençlerimiz varken, Avrupa\'da gerçek bir hayalet olsaydı onu çok geçmeden evimize götürürdük!"', 'notes': 'painting the town/world red: alemlere akmak, ortalığı kasıp kavurmak.'}, {'id': 12, 'text': '"We would put it in a museum in Boston or carry it on the road as a public exhibition."', 'translation': '"Onu Boston\'da bir müzeye koyar veya halka açık bir sergi olarak şehir şehir gezdirirdik."', 'notes': 'public exhibition: halka açık sergi.'}, {'id': 13, 'text': '"I fear that the ghost really exists," said Lord Canterville, smiling gently at his guest\'s spirited words.', 'translation': '"Korkarım ki hayalet gerçekten var," dedi Lord Canterville, misafirinin ateşli sözlerine nazikçe gülümseyerek.', 'notes': 'smiling gently: nazikçe gülümseyerek.'}, {'id': 14, 'text': '"It has been seen by several living members of my family, as well as by the local rector of the parish."', 'translation': '"Ailemin yaşayan birkaç üyesi tarafından olduğu kadar cemaatin yerel papazı tarafından da görüldü."', 'notes': 'local rector: yerel papaz.'}, {'id': 15, 'text': '"After the tragic misfortune of the Duchess, none of our younger servants would stay in the house at night."', 'translation': '"Düşesin yaşadığı o trajik talihsizlikten sonra, genç hizmetkarlarımızın hiçbiri geceleri evde kalmak istemedi."', 'notes': 'tragic misfortune: trajik talihsizlik.'}, {'id': 16, 'text': '"The parish rector himself heard the chains rattling loudly in the library late at night."', 'translation': '"Bölge papazının bizzat kendisi gecenin geç saatlerinde kütüphanede zincirlerin şiddetle şakırdadığını duydu."', 'notes': 'chains rattling: zincirlerin şakırdaması.'}, {'id': 17, 'text': '"I will take the furniture and the ghost at a valuation," Mr. Otis replied with businesslike composure.', 'translation': '"Mobilyaları da hayaleti de takdir edilen değer üzerinden satın alacağım," diye iş bitirici bir sükunetle yanıtladı Bay Otis.', 'notes': 'at a valuation: takdir edilen bedel üzerinden.'}, {'id': 18, 'text': '"I come from a culture that does not believe in ghostly apparitions or medieval superstitions."', 'translation': '"Hayaletimsi görüntülere veya ortaçağ batıl inançlarına inanmayan bir kültürden geliyorum."', 'notes': 'medieval superstitions: ortaçağ batıl inançları.'}, {'id': 19, 'text': '"There is no law of nature that can be suspended simply for the benefit of the British aristocracy!"', 'translation': '"Sırf İngiliz aristokrasisinin hatırı için askıya alınabilecek hiçbir doğa kanunu yoktur!"', 'notes': 'suspended for benefit: yararına askıya alınan.'}, {'id': 20, 'text': 'And so, within a few weeks, the purchase was formally concluded, and the deed of Canterville Chase was signed.', 'translation': "Ve böylece birkaç hafta içinde satın alma işlemi resmen tamamlandı ve Canterville Köşkü'nün tapusu imzalandı.", 'notes': 'purchase concluded: satın alma tamamlandı.'}]}, {'page_no': 2, 'title': "Lord Canterville's Warning and American Logic", 'tr_title': "Lord Canterville'nin Uyarısı ve Amerikan Mantığı", 'vocab_focus': [('reckless', 'pervasız, aldırışsız'), ('heirloom', 'aile yadigarı'), ('ancestor', 'ata, ecdat'), ('valuation', 'değer biçme, kıymet takdiri'), ('thunderstorm', 'fırtına, gök gürültülü sağanak'), ('dusk', 'alacakaranlık'), ('avenue', 'ağaçlıklı yol, cadde'), ('arrival', 'varış, geliş')], 'sentences': [{'id': 21, 'text': "Lord Canterville was amused by the American gentleman's fearless pragmatism, though he maintained his polite British reserve.", 'translation': 'Lord Canterville, kibar İngiliz mesafesini korusa da Amerikalı beyefendinin korkusuz pragmatizminden keyif almıştı.', 'notes': 'fearless pragmatism: korkusuz pragmatizm.'}, {'id': 22, 'text': '"You are certainly very natural in America," the English lord remarked with a genial smile.', 'translation': '"Amerika\'da kesinlikle çok doğalsınız," dedi İngiliz lordu samimi bir tebessümle.', 'notes': 'genial smile: samimi tebessüm.'}, {'id': 23, 'text': '"If you don\'t mind a ghost in the house, that is entirely your own affair."', 'translation': '"Eğer evde bir hayalet bulunmasını dert etmiyorsanız, bu tamamen sizin kendi bileceğiniz iştir."', 'notes': 'entirely your own affair: tamamen sizin kendi bileceğiniz iş.'}, {'id': 24, 'text': '"Only remember that I warned you honestly before you paid a single dollar for the property."', 'translation': '"Yalnızca mülk için tek bir dolar ödemeden önce sizi dürüstçe uyardığımı unutmayın."', 'notes': 'warned honestly: dürüstçe uyardı.'}, {'id': 25, 'text': '"I consider the ghost an heirloom of the family, and as such, it shall be treated with respect,"', 'translation': '"Hayaleti ailenin bir yadigarı sayıyorum ve bu sıfatla kendisine saygıyla muamele edilecektir,"', 'notes': 'heirloom of family: ailenin yadigarı.'}, {'id': 26, 'text': "Mr. Otis shook Lord Canterville's hand warmly, and the two men parted in high mutual esteem.", 'translation': "Bay Otis, Lord Canterville'in elini hararetle sıktı ve iki adam karşılıklı yüksek bir saygıyla ayrıldılar.", 'notes': 'mutual esteem: karşılıklı saygı.'}, {'id': 27, 'text': 'Toward the close of July, the American Minister and his entire household traveled down to Ascot by train.', 'translation': "Temmuz ayının sonlarına doğru Amerikalı Elçi ve tüm ailesi trenle Ascot'a doğru yola çıktı.", 'notes': 'toward the close: sonlarına doğru.'}, {'id': 28, 'text': 'At the railway station, a spacious wagonette was waiting to convey them to their new countryside residence.', 'translation': 'Tren istasyonunda, onları yeni kır konutlarına götürmek üzere geniş bir atlı fayton bekliyordu.', 'notes': 'spacious wagonette: geniş atlı fayton.'}, {'id': 29, 'text': 'It was a lovely summer evening, and the fragrant air smelled deliciously of pine needles and wild honeysuckle.', 'translation': 'Nefis bir yaz akşamıydı ve mis kokulu hava çam iğneleri ile yabani hanımeli gibi leziz kokuyordu.', 'notes': 'wild honeysuckle: yabani hanımeli.'}, {'id': 30, 'text': 'Now and then, they heard a wood pigeon calling softly to its mate among the thick boughs.', 'translation': 'Zaman zaman kalın dallar arasından eşine usulca seslenen bir yaban güvercininin sesini duyuyorlardı.', 'notes': 'wood pigeon: yaban güvercini.'}, {'id': 31, 'text': 'Little squirrels peered curiously at them from the beech trees as the heavy carriage rolled past.', 'translation': 'Ağır araba yanlarından geçerken küçük sincaplar kayın ağaçlarından merakla onlara baktı.', 'notes': 'peered curiously: merakla baktı.'}, {'id': 32, 'text': 'Pheasants fluttered across the dusty road, their bright feathers gleaming in the golden setting sun.', 'translation': 'Parlak tüyleri batan altın sarısı güneşte parıldayan sülünler tozlu yol boyunca kanat çırptı.', 'notes': 'pheasants fluttered: sülünler kanat çırptı.'}, {'id': 33, 'text': 'However, as they entered the long avenue of ancient oaks that led to Canterville Chase, the sky darkened abruptly.', 'translation': "Fakat Canterville Köşkü'ne uzanan asırlık meşe ağaçlıklı uzun yola girdiklerinde gökyüzü aniden karardı.", 'notes': 'darkened abruptly: aniden karardı.'}, {'id': 34, 'text': 'A strange and sullen stillness seemed to hold the atmosphere in an unnatural, suffocating grip.', 'translation': 'Tuhaf ve asık suratlı bir durgunluk, atmosferi doğal olmayan boğucu bir pençede tutar gibiydi.', 'notes': 'sullen stillness: asık suratlı durgunluk.'}, {'id': 35, 'text': 'A great flight of rooks rose noisily above their heads, cawing harshly as they circled the treetops.', 'translation': 'Ağaç tepelerinde dönerken sertçe gaklayarak başlarının üzerinden gürültüyle büyük bir karga sürüsü havalandı.', 'notes': 'flight of rooks: karga sürüsü.'}, {'id': 36, 'text': 'Heavy raindrops began to patter loudly upon the leather hood of the wagonette.', 'translation': 'Ağır yağmur damlaları faytonun deri tentesine gürültüyle vurmaya başladı.', 'notes': 'began to patter: pıtır pıtır vurmaya başladı.'}, {'id': 37, 'text': '"It looks as though we are going to have a genuine English thunderstorm!" Washington Otis observed.', 'translation': '"Görünüşe göre hakiki bir İngiliz fırtınasıyla karşılaşacağız!" dedi Washington Otis.', 'notes': 'genuine thunderstorm: hakiki fırtına.'}, {'id': 38, 'text': 'Before they reached the house, large drops of cold rain had fallen into a steady, furious downpour.', 'translation': 'Onlar eve ulaşmadan önce soğuk yağmurun iri damlaları kesintisiz, şiddetli bir sağanağa dönüştü.', 'notes': 'furious downpour: şiddetli sağanak.'}, {'id': 39, 'text': 'At last, the dark chimneys and gables of Canterville Chase appeared through the dripping woodland.', 'translation': "Nihayet sırılsıklam koruluğun arasından Canterville Köşkü'nün karanlık bacaları ve sivri çatıları göründü.", 'notes': 'dripping woodland: damlayan/ıslak koruluk.'}, {'id': 40, 'text': 'The carriage swept up the circular gravel drive, halting before the imposing Tudor entrance.', 'translation': 'Fayton dairesel çakıllı yoldan yukarı hızla ilerledi ve görkemli Tudor girişinin önünde durdu.', 'notes': 'imposing entrance: görkemli giriş.'}]}, {'page_no': 3, 'title': 'The Otis Family Arrives at the Manor', 'tr_title': 'Otis Ailesi Malikâneye Varıyor', 'vocab_focus': [('matriarch', 'aile reisi kadın, anne'), ('housekeeper', 'kahya kadın'), ('apron', 'önlük'), ('courteous', 'nazik, kibar'), ('porch', 'sundurma, giriş kapısı önü'), ('entrance', 'giriş'), ('twins', 'ikizler'), ('tomboy', 'erkek fatma, hareketli kız')], 'sentences': [{'id': 41, 'text': 'The Otis family was a splendid example of modern, energetic American domesticity.', 'translation': 'Otis ailesi, modern ve enerjik Amerikan aile hayatının muhteşem bir örneğiydi.', 'notes': 'splendid example: muhteşem örnek.'}, {'id': 42, 'text': 'Mrs. Otis was a remarkably handsome woman of middle age, with fine eyes and an exceptional constitution.', 'translation': 'Bayan Otis güzel gözleri ve olağanüstü bünyesiyle orta yaşlı, son derece alımlı bir kadındı.', 'notes': 'exceptional constitution: olağanüstü bünye/sağlık.'}, {'id': 43, 'text': 'Indeed, she had preserved all the brisk health and vivacity of her youth in Manhattan.', 'translation': "Nitekim Manhattan'daki gençliğinin o canlı sağlığını ve hayat doluluğunu bütünüyle korumuştu.", 'notes': 'brisk health: zinde sağlık.'}, {'id': 44, 'text': 'Her eldest son, Washington, was a fair-haired, good-looking young fellow of excellent common sense.', 'translation': 'En büyük oğlu Washington, kusursuz sağduyuya sahip sarışın, yakışıklı bir genç adamdı.', 'notes': 'common sense: sağduyu.'}, {'id': 45, 'text': 'He was famous in diplomatic circles for having danced the German cotillion three seasons running in Newport.', 'translation': "Newport'ta üç sezon boyunca aralıksız Alman kotilyonu dansı yapmasıyla diplomatik çevrelerde ün salmıştı.", 'notes': 'diplomatic circles: diplomatik çevreler.'}, {'id': 46, 'text': 'Miss Virginia E. Otis was a sweet, graceful girl of fifteen, slender and lovely as a gazelle.', 'translation': 'Bayan Virginia E. Otis on beş yaşında, bir ceylan gibi narin ve sevimli, tatlı ve zarif bir kızdı.', 'notes': 'graceful girl: zarif kız.'}, {'id': 47, 'text': 'With her large azure-blue eyes and golden curls, she was a skilled horsewoman who once raced the Duke of Cheshire.', 'translation': 'İri gök mavisi gözleri ve altın bukleleriyle bir keresinde Cheshire Dükü ile yarışmış mahir bir biniciydi.', 'notes': 'skilled horsewoman: usta kadın binici.'}, {'id': 48, 'text': 'The youngest children were twin boys, usually called "The Stars and Stripes", who were always in mischief.', 'translation': 'En küçük çocuklar genellikle "Yıldızlar ve Çizgiler" diye anılan ve daima yaramazlık peşinde koşan ikiz erkeklerdi.', 'notes': 'always in mischief: hep yaramazlıkta.'}, {'id': 49, 'text': 'They were delightful boys, and with the exception of the worthy Minister, the only true republicans of the family.', 'translation': 'Sevimli çocuklardı ve saygıdeğer Elçi hariç tutulursa ailenin yegane gerçek cumhuriyetçileriydiler.', 'notes': 'true republicans: gerçek cumhuriyetçiler.'}, {'id': 50, 'text': 'Standing upon the stone porch to receive them was an elderly woman dressed neatly in black silk.', 'translation': 'Onları karşılamak için taş sundurmada bekleyen kişi, siyah ipekten düzgünce giyinmiş yaşlı bir kadındı.', 'notes': 'stone porch: taş sundurma.'}, {'id': 51, 'text': 'She wore a white cap and apron, looking every inch the traditional British housekeeper.', 'translation': 'Geleneksel bir İngiliz kahyasını tepeden tırnağa yansıtarak beyaz bir başlık ve önlük takmıştı.', 'notes': 'traditional housekeeper: geleneksel kahya.'}, {'id': 52, 'text': 'This was Mrs. Umney, the faithful housekeeper whom Lord Canterville had recommended should be retained.', 'translation': "Bu kişi, Lord Canterville'in görevinde tutulmasını tavsiye ettiği sadık kahya Bayan Umney idi.", 'notes': 'faithful housekeeper: sadık kahya.'}, {'id': 53, 'text': 'She made a deep curtsy to each member of the family as they stepped out of the wagonette.', 'translation': 'Aile üyeleri faytondan inerken her birine derin bir reverans yaptı.', 'notes': 'made a deep curtsy: derin bir reverans yaptı.'}, {'id': 54, 'text': '"Welcome to Canterville Chase, ladies and gentlemen," she said in an old-fashioned, respectful manner.', 'translation': '"Canterville Köşkü\'ne hoş geldiniz hanımefendiler ve beyefendiler," dedi eski usul, saygılı bir tavırla.', 'notes': 'respectful manner: saygılı tavır.'}, {'id': 55, 'text': 'She led them through the grand Tudor hall into the library, a long, low room with dark oak paneling.', 'translation': 'Onları görkemli Tudor salonundan geçirerek koyu renk meşe kaplamalı, uzun ve basık tavanlı kütüphaneye götürdü.', 'notes': 'dark oak paneling: koyu meşe kaplama.'}, {'id': 56, 'text': 'At the far end of the room stood a vast stained-glass window that looked out upon the stormy park.', 'translation': 'Odanın uzak ucunda, fırtınalı parka bakan kocaman bir vitray pencere duruyordu.', 'notes': 'stained-glass window: vitray pencere.'}, {'id': 57, 'text': 'A bright fire burned cheerfully in the enormous hearth, casting a warm glow across the book-lined walls.', 'translation': 'Kitaplarla kaplı duvarlara sıcak bir ışıltı saçarak devasa şöminede neşeyle parlak bir ateş yanıyordu.', 'notes': 'book-lined walls: kitaplarla kaplı duvarlar.'}, {'id': 58, 'text': 'Tea had been laid out upon a low table, and the travelers gladly sat down to refresh themselves.', 'translation': 'Çay alçak bir masanın üzerine serilmişti ve yolcular ferahlamak için memnuniyetle oturdular.', 'notes': 'refresh themselves: ferahlamak, dinlenmek.'}, {'id': 59, 'text': 'The rain beat hard against the window panes, and sudden gusts of wind moaned through the ancient chimneys.', 'translation': 'Yağmur pencere camlarına sertçe vuruyor, ani rüzgar uğultuları asırlık bacalardan inliyordu.', 'notes': 'gusts of wind: rüzgar uğultuları/esintileri.'}, {'id': 60, 'text': 'They all agreed that, despite the somber weather, Canterville Chase was a magnificent historic residence.', 'translation': "Kasvetli havaya rağmen Canterville Köşkü'nün muhteşem tarihi bir konut olduğu konusunda hepsi hemfikirdi.", 'notes': 'magnificent historic residence: muhteşem tarihi konut.'}]}, {'page_no': 4, 'title': 'The Ineffaceable Blood-Stain on the Library Floor', 'tr_title': 'Kütüphane Zeminindeki Çıkmayan Kan Lekesi', 'vocab_focus': [('stain', 'leke'), ('hearth', 'şömine, ocak'), ('ineffaceable', 'silinmez, çıkmaz'), ('murder', 'cinayet, öldürmek'), ('gruesome', 'korkunç, tüyler ürpertici'), ('tragedy', 'facia, trajedi'), ('spilled', 'dökülmüş'), ('historical', 'tarihi')], 'sentences': [{'id': 61, 'text': 'While pouring tea, Mrs. Otis suddenly noticed a curious dull red patch on the floor beside the fireplace.', 'translation': 'Çay doldururken Bayan Otis ansızın şöminenin yanındaki zeminde tuhaf, donuk kırmızı bir leke fark etti.', 'notes': 'curious dull red patch: tuhaf donuk kırmızı leke.'}, {'id': 62, 'text': '"I am afraid something has been spilt there, Mrs. Umney," said Mrs. Otis pointing to the spot.', 'translation': '"Korkarım oraya bir şey dökülmüş Bayan Umney," dedi Bayan Otis noktayı işaret ederek.', 'notes': 'something has been spilt: bir şey dökülmüş.'}, {'id': 63, 'text': '"Yes, madam," replied the old housekeeper in a low, mysterious whisper, "blood has been spilt on that spot."', 'translation': '"Evet efendim," diye yanıtladı yaşlı kahya kısık, esrarengiz bir fısıltıyla, "o noktaya kan döküldü."', 'notes': 'mysterious whisper: esrarengiz fısıltı.'}, {'id': 64, 'text': '"How thoroughly dreadful!" cried Mrs. Otis in genuine disgust; "I don\'t care at all for blood-stains in a sitting room!"', 'translation': '"Ne kadar da berbat!" diye haykırdı Bayan Otis sahici bir tiksintiyle; "Oturma odasında kan lekelerinden hiç hoşlanmam!"', 'notes': 'genuine disgust: sahici tiksinti.'}, {'id': 65, 'text': '"It must be cleaned up and removed at once!"', 'translation': '"Derhal temizlenmeli ve ortadan kaldırılmalıdır!"', 'notes': 'at once: derhal, hemen.'}, {'id': 66, 'text': 'The elderly housekeeper smiled with solemn pride and answered in the same grave, quiet voice.', 'translation': 'Yaşlı kahya vakur bir gururla gülümsedi ve aynı ağırbaşlı, sakin ses tonuyla yanıt verdi.', 'notes': 'solemn pride: vakur gurur.'}, {'id': 67, 'text': '"It is the blood of Lady Eleanore de Canterville, who was murdered on that exact spot in 1575."', 'translation': '"1575 yılında tam o noktada katledilen Leydi Eleanore de Canterville\'in kanıdır o."', 'notes': 'exact spot: tam o nokta.'}, {'id': 68, 'text': '"She was slain by her own husband, Sir Simon de Canterville, in a fit of jealous fury."', 'translation': '"Kıskançlık krizine giren bizzat kendi kocası Sir Simon de Canterville tarafından katledildi."', 'notes': 'jealous fury: kıskançlık öfkesi.'}, {'id': 69, 'text': '"Sir Simon survived his unfortunate lady for nine years, but disappeared suddenly under very mysterious circumstances."', 'translation': '"Sir Simon talihsiz eşinden sonra dokuz yıl daha yaşadı fakat çok esrarengiz koşullar altında aniden kayboldu."', 'notes': 'mysterious circumstances: esrarengiz koşullar.'}, {'id': 70, 'text': '"His body was never discovered, but his guilty spirit still walks these corridors at midnight."', 'translation': '"Cesedi hiçbir zaman bulunamadı fakat suçlu ruhu hâlâ gece yarıları bu koridorlarda dolaşır."', 'notes': 'guilty spirit: suçlu ruh.'}, {'id': 71, 'text': '"The blood-stain has been much admired by tourists and scholars who have visited the Chase."', 'translation': '"Bu kan lekesi köşkü ziyaret eden turistler ve akademisyenler tarafından hep büyük bir hayranlıkla karşılanmıştır."', 'notes': 'much admired: çok hayranlık duyulan.'}, {'id': 72, 'text': '"It cannot be removed by any soap, water, or chemical substance known to mortal man."', 'translation': '"Fani insanın bildiği hiçbir sabun, su veya kimyasal maddeyle çıkarılamaz."', 'notes': 'mortal man: fani insan.'}, {'id': 73, 'text': '"Generations of housekeepers have scrubbed the oak with sand and lye, yet the blood remains untouched."', 'translation': '"Nesiller boyu kahyalar meşe tahtayı kum ve çamaşır sodasıyla ovdular, yine de kan el değmemiş gibi kaldı."', 'notes': 'sand and lye: kum ve çamaşır sodası/kül suyu.'}, {'id': 74, 'text': '"It is a sacred heirloom of the house, a testament to the tragic curse upon the family."', 'translation': '"Evin kutsal bir yadigarıdır, aile üzerindeki trajik lanetin bir kanıtıdır o."', 'notes': 'sacred heirloom: kutsal yadigar.'}, {'id': 75, 'text': 'The Otis family listened to the grim tale without showing the slightest sign of horror or awe.', 'translation': 'Otis ailesi bu kasvetli hikayeyi en ufak bir dehşet veya korku belirtisi göstermeden dinledi.', 'notes': 'slightest sign: en ufak belirti.'}, {'id': 76, 'text': 'The twins grinned at each other, already wondering how they might turn the story into a game.', 'translation': 'İkizler hikayeyi nasıl bir oyuna dönüştürebileceklerini şimdiden merak ederek birbirlerine sırıttılar.', 'notes': 'grinned at each other: birbirlerine sırıttılar.'}, {'id': 77, 'text': 'Virginia stroked her pet kitten softly, feeling only mild pity for the unfortunate murdered lady.', 'translation': 'Virginia kucağındaki yavru kediyi usulca okşadı; talihsiz maktul hanımefendiye yalnızca hafif bir acıma duydu.', 'notes': 'mild pity: hafif bir acıma.'}, {'id': 78, 'text': "Mr. Otis took a sip of his tea and nodded thoughtfully, evaluating the housekeeper's words.", 'translation': 'Bay Otis çayından bir yudum aldı ve kahyanın sözlerini tartarak düşünceli bir şekilde başını salladı.', 'notes': 'took a sip: bir yudum aldı.'}, {'id': 79, 'text': '"An interesting legend, no doubt," said Mr. Otis, "but completely unscientific in its premise."', 'translation': '"İlginç bir efsane olduğuna şüphe yok," dedi Bay Otis, "fakat önermesi açısından tamamen bilimsellikten uzak."', 'notes': 'unscientific in premise: önermesi itibarıyla bilim dışı.'}, {'id': 80, 'text': 'Washington Otis stood up from his chair, a confident smile playing upon his lips.', 'translation': 'Dudaklarında kendinden emin bir tebessüm oynaşarak Washington Otis sandalyesinden ayağa kalktı.', 'notes': 'confident smile: kendinden emin tebessüm.'}]}, {'page_no': 5, 'title': "Pinkerton's Champion Stain Remover", 'tr_title': 'Pinkerton Şampiyon Leke Çıkarıcı', 'vocab_focus': [('detergent', 'deterjan, temizlik maddesi'), ('scourer', 'ovucu, temizleyici'), ('triumph', 'zafer, büyük başarı'), ('flash', 'parlama, çakma'), ('thunder', 'gök gürültüsü'), ('faint', 'bayılmak'), ('superstitious', 'batıl inançlı'), ('miracle', 'mucize')], 'sentences': [{'id': 81, 'text': '"That is all absolute nonsense!" cried Washington Otis with breezy American confidence.', 'translation': '"Bütün bunlar külliyen saçmalık!" diye haykırdı Washington Otis o ferah Amerikan özgüveniyle.', 'notes': 'absolute nonsense: külliyen saçmalık.'}, {'id': 82, 'text': '"Pinkerton\'s Champion Stain Remover and Incomparable Detergent will clean it up in no time at all!"', 'translation': '"Pinkerton Şampiyon Leke Çıkarıcı ve Emsalsiz Deterjanı onu göz açıp kapayana kadar temizler!"', 'notes': 'in no time: göz açıp kapayana kadar.'}, {'id': 83, 'text': 'Before the terrified housekeeper could utter a word of protest, the young man had fallen upon his knees.', 'translation': 'Dehşete kapılmış kahya tek bir itiraz kelimesi dahi edemeden genç adam dizlerinin üzerine çökmüştü bile.', 'notes': 'fallen upon knees: dizlerinin üzerine çöktü.'}, {'id': 84, 'text': 'He produced a small black stick of chemical compound from his travel waistcoat pocket.', 'translation': 'Seyahat yeleğinin cebinden kimyasal bileşimli küçük siyah bir çubuk çıkardı.', 'notes': 'chemical compound: kimyasal bileşim.'}, {'id': 85, 'text': 'Rapidly, he began scouring the three-hundred-year-old blood-stain with vigorous, practiced strokes.', 'translation': 'Hızlı bir şekilde, çevik ve alışkın hareketlerle üç yüz yıllık kan lekesini ovmaya başladı.', 'notes': 'practiced strokes: alışkın hareketler/vuruşlar.'}, {'id': 86, 'text': 'In less than ten seconds, the dark red stain had completely vanished from the surface of the floor!', 'translation': 'On saniyeden kısa bir süre içinde koyu kırmızı leke zeminin yüzeyinden tamamen kayboldu!', 'notes': 'completely vanished: tamamen kayboldu.'}, {'id': 87, 'text': '"I knew Pinkerton would do it!" Washington exclaimed triumphantly, holding up the miraculous cleaning stick.', 'translation': '"Pinkerton\'ın halledeceğini biliyordum!" diye haykırdı Washington zaferle, mucizevi temizlik çubuğunu havaya kaldırarak.', 'notes': 'exclaimed triumphantly: zaferle haykırdı.'}, {'id': 88, 'text': 'He turned around to gaze admiringly at his family, who applauded his prompt scientific solution.', 'translation': 'Çabuk ve bilimsel çözümünü alkışlayan ailesine takdirle bakmak için arkasını döndü.', 'notes': 'prompt scientific solution: çabuk bilimsel çözüm.'}, {'id': 89, 'text': 'Hardly had the words left his mouth when a terrible flash of blue lightning lit up the sombre room.', 'translation': 'Kelimeler ağzından henüz çıkmıştı ki korkunç bir mavi şimşek parıltısı kasvetli odayı aydınlattı.', 'notes': 'flash of lightning: şimşek parıltısı/çakması.'}, {'id': 90, 'text': 'A fearful peal of thunder shook the entire mansion to its medieval foundations.', 'translation': 'Korkunç bir gök gürültüsü patlaması koca malikaneyi ortaçağdan kalma temellerine kadar sarstı.', 'notes': 'peal of thunder: gök gürültüsü patlaması.'}, {'id': 91, 'text': 'The wind howled fiercely through the casements, and everyone started to their feet in momentary alarm.', 'translation': 'Rüzgar kanatlı pencerelerden şiddetle uludu ve herkes bir anlık telaşla ayağa fırladı.', 'notes': 'started to feet: ayağa fırladı.'}, {'id': 92, 'text': 'Mrs. Umney let out a piercing shriek of superstitious terror and fainted dead away upon the hearthrug.', 'translation': 'Bayan Umney batıl inançlı bir dehşetle tiz bir çığlık attı ve şömine paspasının üzerine boylu boyunca bayıldı.', 'notes': 'fainted dead away: boylu boyunca bayıldı.'}, {'id': 93, 'text': '"What a monstrous climate!" said the American Minister calmly, lighting a long Havana cigar.', 'translation': '"Ne korkunç bir iklim!" dedi Amerikalı Elçi sakince, uzun bir Havana purosu yakarak.', 'notes': 'monstrous climate: korkunç/berbat iklim.'}, {'id': 94, 'text': '"I guess the old country is so overpopulated that they cannot have enough decent weather for everybody."', 'translation': '"Sanırım eski kıta o kadar aşırı nüfuslu ki herkese yetecek kadar düzgün bir hava bulamıyorlar."', 'notes': 'decent weather: düzgün/güzel hava.'}, {'id': 95, 'text': '"I have always been of opinion that emigration is the only thing for England."', 'translation': '"İngiltere için yegane kurtuluşun göç etmek olduğu kanaatini her zaman taşımışımdır."', 'notes': 'emigration: dış göç.'}, {'id': 96, 'text': '"My dear Hiram," cried Mrs. Otis, "what can we do with a woman who faints on our rug?"', 'translation': '"Sevgili Hiram," diye bağırdı Bayan Otis, "halımızın üzerine bayılan bir kadınla ne yapabiliriz ki?"', 'notes': 'faints on rug: halıya bayılır.'}, {'id': 97, 'text': '"Charge it to her like breakages," answered the Minister; "she won\'t faint after that."', 'translation': '"Kırılan dökülen eşyalar gibi maaşından keseriz," diye yanıtladı Elçi; "ondan sonra bir daha bayılmaz."', 'notes': 'charge like breakages: kırılan eşya gibi hesaba katmak/kesmek.'}, {'id': 98, 'text': 'In a few moments, Mrs. Umney certainly came to, looking severely shaken by the unholy events.', 'translation': 'Birkaç dakika içinde Bayan Umney sahiden de kendine geldi; bu uğursuz olaylardan fena halde sarsılmış görünüyordu.', 'notes': 'came to: kendine geldi, ayıltı.'}, {'id': 99, 'text': 'She warned the family that terrible misfortunes would fall upon the house if they challenged the spirit.', 'translation': 'Eğer ruha meydan okurlarsa evin başına korkunç felaketlerin geleceği konusunda aileyi uyardı.', 'notes': 'terrible misfortunes: korkunç felaketler.'}, {'id': 100, 'text': 'However, Mr. and Mrs. Otis warmly reassured her that they feared neither ghosts nor thunderstorms.', 'translation': 'Ne var ki Bay ve Bayan Otis ne hayaletlerden ne de fırtınalardan korktukları konusunda ona sıcacık bir güvence verdiler.', 'notes': 'warmly reassured: sıcacık güvence verdi.'}]}, {'page_no': 6, 'title': 'The Clanking Chains of Sir Simon', 'tr_title': "Sir Simon'ın Şakırdayan Zincirleri", 'vocab_focus': [('corridor', 'koridor'), ('clanking', 'şakırtı, madeni ses'), ('rusted', 'paslanmış'), ('manacle', 'pranga, kelepçe'), ('specter', 'hayalet, tayf'), ('midnight', 'gece yarısı'), ('apparition', 'hortlak, görüntü'), ('slippers', 'terlikler')], 'sentences': [{'id': 101, 'text': 'The storm raged fiercely throughout the entire night, but the Otis family slept soundly until morning.', 'translation': 'Fırtına bütün gece boyunca şiddetle kudurup durdu fakat Otis ailesi sabaha kadar mışıl mışıl uyudu.', 'notes': 'slept soundly: mışıl mışıl uyudu.'}, {'id': 102, 'text': 'The next morning, when they came down to breakfast, they found the terrible stain on the floor once again.', 'translation': 'Ertesi sabah kahvaltıya indiklerinde yerdeki o korkunç lekeyi bir kez daha buldular.', 'notes': 'found the stain: lekeyi buldular.'}, {'id': 103, 'text': '"I don\'t think it can be the fault of the Paragon Detergent," said Washington, examining the spot.', 'translation': '"Bunun Paragon Deterjanı\'nın kusuru olabileceğini hiç sanmıyorum," dedi Washington lekeyi inceleyerek.', 'notes': 'fault of detergent: deterjanın kusuru.'}, {'id': 104, 'text': '"I rubbed it out completely last night; the ghost must be re-dyeing the floorboards."', 'translation': '"Dün gece onu tamamen silip çıkarmıştım; hayalet döşeme tahtalarını yeniden boyuyor olmalı."', 'notes': 're-dyeing floorboards: döşeme tahtalarını yeniden boyamak.'}, {'id': 105, 'text': 'He rubbed it out a second time, but the second morning it appeared again in bright red.', 'translation': 'İkinci kez sildi çıkardı fakat ikinci sabah leke parlak kırmızı renkte yine belirdi.', 'notes': 'rubbed it out: silip çıkardı.'}, {'id': 106, 'text': 'On the third morning, the stain was there again, though the library door had been locked overnight by Mr. Otis himself.', 'translation': 'Kütüphane kapısı bizzat Bay Otis tarafından gece boyunca kilitli tutulmuş olmasına rağmen üçüncü sabah leke yine oradaydı.', 'notes': 'locked overnight: gece boyunca kilitli.'}, {'id': 107, 'text': 'The whole family was now quite interested; the existence of the ghost could no longer be doubted.', 'translation': 'Bütün aile artık epey ilgilenmeye başlamıştı; hayaletin varlığından artık şüphe edilemezdi.', 'notes': 'could no longer be doubted: artık şüphe edilemezdi.'}, {'id': 108, 'text': 'That very night, all doubts regarding the supernatural resident were removed forever.', 'translation': 'Tam o gece doğaüstü sakine dair tüm şüpheler sonsuza dek ortadan kalktı.', 'notes': 'all doubts removed: tüm şüpheler kalktı.'}, {'id': 109, 'text': 'The day had been warm and sunny, and in the cool of the evening, the family took a pleasant drive.', 'translation': 'Gün sıcak ve güneşli geçmişti ve akşamın serinliğinde aile keyifli bir fayton gezintisi yaptı.', 'notes': 'cool of evening: akşam serinliği.'}, {'id': 110, 'text': "They returned at nine o'clock, ate a light supper, and by eleven o'clock the whole house was dark and asleep.", 'translation': 'Saat dokuzda döndüler, hafif bir akşam yemeği yediler ve saat on bir olduğunda bütün ev karanlık ve uykudaydı.', 'notes': 'light supper: hafif akşam yemeği.'}, {'id': 111, 'text': 'Some time after midnight, Mr. Otis was awakened by a singular and irritating noise in the corridor.', 'translation': 'Gece yarısından bir süre sonra Bay Otis koridordaki tuhaf ve sinir bozucu bir gürültüyle uyandı.', 'notes': 'singular and irritating noise: tuhaf ve sinir bozucu gürültü.'}, {'id': 112, 'text': 'It sounded like the clank of heavy iron chains, and seemed to be coming closer to his bedroom door every second.', 'translation': 'Ağır demir zincirlerin şakırtısını andırıyordu ve her saniye yatak odasının kapısına daha da yaklaşıyor gibiydi.', 'notes': 'clank of chains: zincirlerin şakırtısı.'}, {'id': 113, 'text': 'He got up immediately, struck a match, and looked at the clock on his bedside table.', 'translation': 'Derhal kalktı, bir kibrit çaktı ve komodinindeki saate baktı.', 'notes': 'struck a match: kibrit çaktı.'}, {'id': 114, 'text': "It was exactly one o'clock.", 'translation': 'Saat tam biri gösteriyordu.', 'notes': "exactly one o'clock: tam saat bir."}, {'id': 115, 'text': 'Mr. Otis was quite calm, and his pulse did not quicken in the least.', 'translation': 'Bay Otis gayet sakindi ve nabzı zerre kadar bile hızlanmadı.', 'notes': 'pulse did not quicken: nabzı hızlanmadı.'}, {'id': 116, 'text': 'The metallic noise continued outside, accompanied by the distinct sound of slow, hollow footsteps.', 'translation': 'Yavaş, boğuk ayak seslerinin bariz sesi eşliğinde dışarıdaki madeni gürültü devam etti.', 'notes': 'hollow footsteps: boğuk ayak sesleri.'}, {'id': 117, 'text': 'He put on his warm slippers, took a small oblong vial from his dressing-case, and opened the door.', 'translation': 'Sıcak terliklerini giydi, tuvalet masasından küçük dikdörtgen bir şişe aldı ve kapıyı açtı.', 'notes': 'oblong vial: dikdörtgen şişe.'}, {'id': 118, 'text': 'Right in front of him, in the pale moonlight, stood a dreadful and terrifying specter.', 'translation': 'Tam önünde, solgun ay ışığının altında korkunç ve dehşet verici bir hayalet duruyordu.', 'notes': 'dreadful specter: korkunç hayalet.'}, {'id': 119, 'text': 'His eyes were as red as burning coals; his long grey hair fell over his shoulders in matted coils.', 'translation': 'Gözleri kor gibi kırmızıydı; uzun gri saçları keçeleşmiş lüleler halinde omuzlarına dökülüyordu.', 'notes': 'burning coals: korlaşmış kömürler.'}, {'id': 120, 'text': 'His garments, of ancient Tudor cut, were soiled and ragged, and from his wrists and ankles hung heavy, rusty manacles.', 'translation': 'Eski Tudor kesimi giysileri kirli ve paramparçaydı ve bilekleri ile ayak bileklerinden ağır, paslı prangalar sarkıyordu.', 'notes': 'rusty manacles: paslı prangalar.'}]}, {'page_no': 7, 'title': 'Tammany Rising Sun Lubricant', 'tr_title': 'Tammany Rising Sun Makine Yağı', 'vocab_focus': [('lubricant', 'yağlayıcı, makine yağı'), ('friction', 'sürtünme'), ('practical', 'pratik, uygulamalı'), ('insult', 'hakaret, aşağılama'), ('indignant', 'öfkeli, haysiyeti kırılmış'), ('bottle', 'şişe'), ('creak', 'gıcırdamak'), ('astonished', 'şaşkına dönmüş')], 'sentences': [{'id': 121, 'text': 'For three centuries, that ghastly appearance had struck terror into the stoutest British hearts.', 'translation': 'Üç yüzyıl boyunca o korkunç görüntü, en cesur İngiliz yüreklerine bile dehşet salmıştı.', 'notes': 'struck terror: dehşet saldı.'}, {'id': 122, 'text': 'Noble lords had turned white as sheets, and brave soldiers had fled weeping in terror from his presence.', 'translation': 'Asil lordlar çarşaf gibi bembeyaz kesilmiş, cesur askerler onun huzurundan dehşet içinde ağlayarak kaçmıştı.', 'notes': 'white as sheets: çarşaf gibi beyaz.'}, {'id': 123, 'text': 'Yet Mr. Hiram B. Otis did not display the slightest tremor of fright or alarm.', 'translation': 'Yine de Bay Hiram B. Otis en ufak bir korku veya telaş titremesi sergilemedi.', 'notes': 'tremor of fright: korku titremesi.'}, {'id': 124, 'text': '"My dear sir," said Mr. Otis politely, "I really must insist on your oiling those chains."', 'translation': '"Muhterem beyefendi," dedi Bay Otis nezaketle, "şu zincirleri yağlamanız konusunda gerçekten ısrarcıyım."', 'notes': 'insist on oiling: yağlamakta ısrar etmek.'}, {'id': 125, 'text': '"It is quite impossible to sleep with such an unbearable racket going on outside our bedrooms."', 'translation': '"Yatak odalarımızın dışında kopan böylesine dayanılmaz bir patırtıyla uyumak kesinlikle imkansız."', 'notes': 'unbearable racket: dayanılmaz patırtı/gürültü.'}, {'id': 126, 'text': '"I have therefore brought you a small bottle of Tammany Rising Sun Lubricator."', 'translation': '"Bu nedenle size küçük bir şişe Tammany Rising Sun Makine Yağı getirdim."', 'notes': 'bottle of lubricator: makine yağı şişesi.'}, {'id': 127, 'text': '"It is said to be completely efficacious upon a single application, eliminating all metallic friction."', 'translation': '"Tek bir uygulamada bile son derece etkili olduğu, tüm madeni sürtünmeyi ortadan kaldırdığı söylenir."', 'notes': 'completely efficacious: tamamen etkili.'}, {'id': 128, 'text': '"There are several testimonials to that effect on the wrapper from some of our most eminent native divines."', 'translation': '"Ambalajın üzerinde en seçkin yerli din adamlarımızdan bazılarının bu yönde birçok onay beyanı yer almaktadır."', 'notes': 'eminent native divines: seçkin yerli din adamları.'}, {'id': 129, 'text': '"I shall leave the bottle here for you upon this marble hall table by the candles."', 'translation': '"Şişeyi şuradaki mumların yanındaki mermer salon masasının üzerine sizin için bırakıyorum."', 'notes': 'marble hall table: mermer salon masası.'}, {'id': 130, 'text': '"I shall be happy to supply you with a larger quantity should you require more in the future."', 'translation': '"Gelecekte daha fazlasına ihtiyaç duyarsanız size daha büyük miktarda temin etmekten memnuniyet duyarım."', 'notes': 'supply with quantity: miktarca temin etmek.'}, {'id': 131, 'text': 'With these words, the United States Minister placed the bottle carefully upon the table.', 'translation': 'Bu sözlerle Birleşik Devletler Elçisi şişeyi masanın üzerine özenle koydu.', 'notes': 'placed carefully: özenle koydu.'}, {'id': 132, 'text': 'He gave a polite, dignified bow, turned back into his bedroom, and shut the door behind him.', 'translation': 'Kibar, vakur bir selam verdi, yatak odasına geri döndü ve kapıyı arkasından kapattı.', 'notes': 'dignified bow: vakur bir selam.'}, {'id': 133, 'text': 'For a moment, the Canterville ghost stood quite motionless in natural astonishment.', 'translation': 'Bir an için Canterville hayaleti doğal bir şaşkınlık içinde tamamen hareketsiz kaldı.', 'notes': 'quite motionless: tamamen hareketsiz.'}, {'id': 134, 'text': 'His jaw dropped, and he stared at the small bottle of machine oil as if it were a deadly viper.', 'translation': 'Ağzı açık kaldı ve küçük makine yağı şişesine sanki ölümcül bir engerek yılanıymış gibi baka kaldı.', 'notes': 'jaw dropped: ağzı açık kaldı.'}, {'id': 135, 'text': 'Never in his three hundred years of spectral existence had any mortal dared to treat him with such indignity!', 'translation': 'Üç yüz yıllık hayaletlik varoluşunda hiçbir fani ona böylesi bir haysiyetsizlikle muamele etmeye cüret edememişti!', 'notes': 'spectral existence: hayaletsi varoluş.'}, {'id': 136, 'text': 'To be offered American machine oil for his venerable, ancient chains was an intolerable insult!', 'translation': 'Mübarek, asırlık zincirleri için kendisine Amerikan makine yağı teklif edilmesi tahammül edilemez bir hakaretti!', 'notes': 'intolerable insult: tahammül edilemez hakaret.'}, {'id': 137, 'text': 'A wild fury swept through his ghostly marrow; his red eyes blazed like furnaces.', 'translation': 'Vahşi bir öfke hayaletsi iliklerine kadar yayıldı; kırmızı gözleri fırın gibi alev alev parladı.', 'notes': 'blazed like furnaces: fırın gibi alevlendi.'}, {'id': 138, 'text': 'He seized the glass vial with trembling claws and smashed it furiously onto the polished parquet floor.', 'translation': 'Titreyen pençeleriyle cam şişeyi kaptı ve öfkeyle cilalı parke zemine fırlatıp tuzla buz etti.', 'notes': 'smashed furiously: öfkeyle parçaladı.'}, {'id': 139, 'text': 'A dark pool of fragrant machine oil spread across the oak boards, reflecting the pale moonlight.', 'translation': 'Solgun ay ışığını yansıtarak kokulu makine yağından koyu bir birikinti meşe tahtaların üzerine yayıldı.', 'notes': 'dark pool: koyu renk gölcük/birikinti.'}, {'id': 140, 'text': 'He was preparing to utter his famous cavernous death-rattle when another bedroom door opened abruptly!', 'translation': 'Tam o meşhur derin ölüm hırıltısını çıkarmaya hazırlanıyordu ki bir başka yatak odası kapısı aniden açıldı!', 'notes': 'death-rattle: ölüm hırıltısı.'}]}, {'page_no': 8, 'title': "The Insulted Ghost's Retreat", 'tr_title': 'Gururu Kırılan Hayaletin Geri Çekilişi', 'vocab_focus': [('humiliation', 'aşağılanma, zillet'), ('shattered', 'tuzla buz olmuş'), ('wrath', 'gazap, hiddet'), ('retreat', 'geri çekilmek, kaçmak'), ('tapestry', 'duvar halısı'), ('indignity', 'küçük düşme, hakaret'), ('century', 'yüzyıl, asır'), ('wainscot', 'ahşap lambri, duvar kaplaması')], 'sentences': [{'id': 141, 'text': "Just as the phantom raised his spectral arms to curse the house, the door of the twins' room flew wide open.", 'translation': 'Tam hayalet eve lanet okumak için hayaletsi kollarını kaldırmıştı ki ikizlerin odasının kapısı ardına kadar açıldı.', 'notes': 'flew wide open: ardına kadar açıldı.'}, {'id': 142, 'text': 'Two small figures clad in red flannel nightshirts appeared in the doorway, giggling mischievously.', 'translation': 'Kırmızı pazen gecelikler giymiş iki küçük siluet kıkırdayarak kapı eşiğinde belirdi.', 'notes': 'giggling mischievously: yaramazca kıkırdayarak.'}, {'id': 143, 'text': 'Before Sir Simon could summon his terrifying grimace, a heavy feather pillow whizzed past his ear.', 'translation': 'Sir Simon o korkutucu yüz ifadesini takınmaya vakit bulamadan ağır bir kuş tüyü yastık kulağının dibinden vınlayarak geçti.', 'notes': 'whizzed past ear: kulağının yanından vınladı.'}, {'id': 144, 'text': 'A second pillow struck him squarely upon the head, knocking his antique Tudor ruff askew!', 'translation': 'İkinci bir yastık dosdoğru kafasına çarptı ve antika Tudor yakalığını yamulttu!', 'notes': 'struck squarely: tam ortasından/dosdoğru çarptı.'}, {'id': 145, 'text': '"Take that, you old ghost!" the twins yelled in gleeful chorus, preparing a barrage of boots and hairbrushes.', 'translation': '"Al bakalım seni koca hayalet!" diye neşeli bir koro halinde bağırdı ikizler, bir çizme ve saç fırçası yağmuru hazırlayarak.', 'notes': 'gleeful chorus: neşeli koro.'}, {'id': 146, 'text': 'The Canterville ghost let out a wild groan of outraged dignity and vanished instantly into thin air.', 'translation': 'Canterville hayaleti gururu kırılmış bir haysiyetin vahşi iniltisini kopardı ve bir anda havada yok oldu.', 'notes': 'vanished into thin air: havaya karışıp yok oldu.'}, {'id': 147, 'text': 'He swept down the grand staircase like a blast of freezing winter wind, his heart burning with humiliation.', 'translation': 'Yüreği aşağılanmanın acısıyla yanarak dondurucu bir kış rüzgarı gibi büyük merdivenlerden aşağı süzüldü.', 'notes': 'burning with humiliation: aşağılanmanın acısıyla yanan.'}, {'id': 148, 'text': 'He melted through the heavy wainscoting of the corridor and retired to his secret chamber in the west wing.', 'translation': 'Koridorun ağır ahşap lambrisinin içinden eriyip geçti ve batı kanadındaki gizli odasına çekildi.', 'notes': 'melted through wainscoting: ahşap lambrinin içinden eriyip geçti.'}, {'id': 149, 'text': 'Once safely inside his dark sanctuary, he sank down onto a dusty stone bench and breathed heavily.', 'translation': 'Karanlık sığınağının içine güvenle girdiğinde tozlu bir taş sıraya çöktü ve ağır ağır soluk aldı.', 'notes': 'dark sanctuary: karanlık sığınak.'}, {'id': 150, 'text': 'Never, in all his three hundred years of glorious haunting, had he been so grossly and vulgarized treated.', 'translation': 'Üç yüz yıllık o şanlı hayaletlik kariyerinde hiçbir zaman bu kadar kaba ve bayağı bir muamele görmemişti.', 'notes': 'glorious haunting: şanlı hayaletlik/musallat olma.'}, {'id': 151, 'text': 'He thought of the Dowager Duchess of Bolton, whom he had frightened into fits before her dressing mirror.', 'translation': "Tuvalet aynasının önünde nöbetler geçirtecek kadar korkuttuğu dul Bolton Düşesi'ni düşündü.", 'notes': 'frightened into fits: krizlere sokacak kadar korkuttu.'}, {'id': 152, 'text': 'He remembered the four housemaids who had gone hysterical when he merely smiled at them from the pantry.', 'translation': 'Kilere yalnızca tebessümle baktığı için histeri krizine giren dört hizmetçi kızı hatırladı.', 'notes': 'gone hysterical: histeri krizine girdi.'}, {'id': 153, 'text': 'He recalled the parish rector, whose candle he had blown out in the vaulted corridor at midnight.', 'translation': 'Gece yarısı tonozlu koridorda mumunu üfleyip söndürdüğü bölge papazını anımsadı.', 'notes': 'blown out candle: mumu üfledi.'}, {'id': 154, 'text': 'And now, modern Americans had offered him machine oil and pelted him with bedroom pillows!', 'translation': 'Ve şimdi modern Amerikalılar ona makine yağı teklif etmiş ve yatak odası yastıkları fırlatmışlardı!', 'notes': 'pelted with pillows: yastık yağmuruna tuttu.'}, {'id': 155, 'text': '"It is intolerable! It is an outrage against all the traditions of English ghostcraft!" Sir Simon hissed.', 'translation': '"Bu tahammül edilemez! İngiliz hayaletlik geleneklerinin tamamına karşı yapılmış bir hakarettir!" diye tısladı Sir Simon.', 'notes': 'traditions of ghostcraft: hayaletlik zanaatı gelenekleri.'}, {'id': 156, 'text': 'For hours, he sat in the cold gloom, plotting a terrible and artistic revenge against the intruders.', 'translation': 'Saatler boyunca soğuk karanlıkta oturdu; davetsiz misafirlere karşı korkunç ve sanatsal bir intikam tezgahladı.', 'notes': 'plotting revenge: intikam tezgahlamak/planlamak.'}, {'id': 157, 'text': 'He would assume his famous role of "Red Reuben, or the Strangled Babe", and petrify the impudent twins.', 'translation': 'Meşhur "Kızıl Reuben veya Boğulmuş Bebek" rolüne bürünecek ve o küstah ikizlerin kanını donduracaktı.', 'notes': 'petrify the twins: ikizlerin kanını dondurmak/taş kesmek.'}, {'id': 158, 'text': 'As for the insolent Minister, he would appear at the foot of his bed and stab himself three times in the throat.', 'translation': "Küstah Elçi'ye gelince, yatağının ayakucunda belirecek ve kendi boğazına üç kez hançer saplayacaktı.", 'notes': 'stab himself: kendini hançerlemek.'}, {'id': 159, 'text': 'He swore by all the dark powers of the underworld that Canterville Chase would remember the wrath of its master.', 'translation': 'Yeraltı dünyasının tüm karanlık güçleri üzerine yemin etti ki Canterville Köşkü efendisinin gazabını hatırlayacaktı.', 'notes': 'swore by dark powers: karanlık güçler üzerine yemin etti.'}, {'id': 160, 'text': 'With a grim chuckle echoing through the stone vault, the ancient ghost resolved to strike the following evening.', 'translation': 'Taş tonozda yankılanan asık bir kıkırdamayla yaşlı hayalet ertesi akşam darbe indirmeye karar verdi.', 'notes': 'resolved to strike: darbe indirmeye karar verdi.'}]}, {'page_no': 9, 'title': 'The Shifting Hues of the Chameleon Stain', 'tr_title': 'Bukalemun Lekenin Değişen Renkleri', 'vocab_focus': [('chameleon', 'bukalemun'), ('emerald green', 'zümrüt yeşili'), ('vermilion', 'parlak kırmızı, zincifre'), ('watercolor', 'sulu boya'), ('pigments', 'boya maddeleri, pigmentler'), ('palette', 'renk paleti'), ('discussion', 'tartışma, müzakere'), ('mystery', 'gizem, sır')], 'sentences': [{'id': 161, 'text': 'For several days after his midnight humiliation, the Canterville ghost kept entirely to his secluded den.', 'translation': 'Gece yarısı yaşadığı aşağılanmanın ardından birkaç gün boyunca Canterville hayaleti tamamen kuytu inine çekildi.', 'notes': 'kept to his den: inine çekildi.'}, {'id': 162, 'text': 'However, the famous blood-stain upon the library floor continued to be renewed every single night.', 'translation': 'Ne var ki kütüphane zeminindeki o meşhur kan lekesi her gece istisnasız yenilenmeye devam etti.', 'notes': 'continued to be renewed: yenilenmeye devam etti.'}, {'id': 163, 'text': "Every morning, Washington Otis diligently scoured it away with Pinkerton's Champion Stain Remover.", 'translation': 'Her sabah Washington Otis, Pinkerton Şampiyon Leke Çıkarıcı ile lekeyi gayretle ovalayıp çıkardı.', 'notes': 'diligently scoured: gayretle ovaladı.'}, {'id': 164, 'text': 'Yet each morning before breakfast, the dark patch was found reappearing in the most extraordinary colors.', 'translation': 'Yine de her sabah kahvaltıdan önce o koyu leke en olağandışı renklerde yeniden belirmiş olarak bulunuyordu.', 'notes': 'extraordinary colors: olağandışı renkler.'}, {'id': 165, 'text': 'On Tuesday morning, it was of a dull, brownish red like dried arterial blood.', 'translation': 'Salı sabahı kurumuş atardamar kanı gibi donuk, kahverengimsi bir kırmızıdaydı.', 'notes': 'arterial blood: atardamar kanı.'}, {'id': 166, 'text': 'On Wednesday, it shone with the brilliant crimson hue of freshly spilled vermilion wine.', 'translation': 'Çarşamba günü yeni dökülmüş nar kırmızısı şarap gibi parlak bir al renkle parıldıyordu.', 'notes': 'brilliant crimson hue: parlak al renk.'}, {'id': 167, 'text': 'On Thursday, when the family came down to breakfast, they found it turned to a rich, deep imperial purple.', 'translation': 'Perşembe günü aile kahvaltıya indiğinde lekenin zengin, koyu bir imparatorluk moruna dönüştüğünü gördü.', 'notes': 'imperial purple: imparatorluk moru.'}, {'id': 168, 'text': 'Most astonishing of all, on Friday morning the stain appeared in a bright, vivid emerald green!', 'translation': 'Hepsinden şaşırtıcı olanı ise cuma sabahı lekenin parlak, canlı bir zümrüt yeşili renginde belirmesiydi!', 'notes': 'vivid emerald green: canlı zümrüt yeşili.'}, {'id': 169, 'text': 'These kaleidoscopic variations naturally caused a great deal of amusement among the younger members of the party.', 'translation': 'Bu rengarenk bukalemunsu değişimler, topluluğun genç üyeleri arasında doğal olarak büyük bir eğlenceye yol açtı.', 'notes': 'kaleidoscopic variations: rengarenk/çeşitli değişimler.'}, {'id': 170, 'text': 'Bets on the respective colors were freely made every evening by the twins and Washington.', 'translation': 'İkizler ve Washington tarafından her akşam çıkacak renklere dair serbestçe iddiaya giriliyordu.', 'notes': 'bets were freely made: serbestçe iddiaya girildi.'}, {'id': 171, 'text': 'The only person who did not enter into the humor of the situation was sweet little Virginia.', 'translation': 'Durumun mizahına katılmayan tek kişi sevimli küçük Virginia idi.', 'notes': 'enter into humor: espriye/mizaha katılmak.'}, {'id': 172, 'text': 'For some unexplained reason, she was always distressed at the sight of the emerald green stain.', 'translation': 'Açıklanamayan bir nedenden ötürü zümrüt yeşili lekeyi gördüğünde her zaman derin bir üzüntü duyuyordu.', 'notes': 'distressed at sight: gördüğünde üzülen.'}, {'id': 173, 'text': 'She nearly cried the morning it turned green, and looked very thoughtful and pensive all through the day.', 'translation': 'Rengi yeşile döndüğü sabah neredeyse ağlayacaktı ve bütün gün boyunca çok düşünceli ve kederli göründü.', 'notes': 'thoughtful and pensive: düşünceli ve kederli.'}, {'id': 174, 'text': 'The truth was that she had discovered that her private box of Newman watercolor paints was missing several cakes.', 'translation': 'İşin aslı, Newman marka suluboya kutusundan birkaç boya kalıbının eksildiğini keşfetmiş olmasıydı.', 'notes': 'missing several cakes: birkaç kalıbı eksik.'}, {'id': 175, 'text': 'The ghost had stolen her cobalt blue and brilliant viridian green to keep up the family tradition on the floor!', 'translation': 'Hayalet, zemindeki aile geleneğini sürdürmek için kızın kobalt mavisini ve parlak zümrüt yeşilini çalmıştı!', 'notes': 'keep up tradition: geleneği sürdürmek.'}, {'id': 176, 'text': 'She was too kind-hearted to betray the secret, though she deeply resented the loss of her best paints.', 'translation': 'En iyi boyalarının kaybolmasına çok içerlese de sırrı açığa vuramayacak kadar iyi kalpliydi.', 'notes': 'deeply resented: çok içerledi/gücendi.'}, {'id': 177, 'text': 'Mr. Otis wrote an amusing letter to his government on the chemical transformation of spectral blood.', 'translation': 'Bay Otis hayalet kanının kimyasal dönüşümü üzerine hükümetine eğlenceli bir mektup yazdı.', 'notes': 'chemical transformation: kimyasal dönüşüm.'}, {'id': 178, 'text': 'Mrs. Otis wondered whether green blood was a common symptom among the ancient Norman nobility.', 'translation': 'Bayan Otis yeşil kanın eski Norman soyluları arasında yaygın bir belirti olup olmadığını merak etti.', 'notes': 'common symptom: yaygın belirti.'}, {'id': 179, 'text': 'The discussions at the dinner table were lively, analytical, and entirely free from medieval terror.', 'translation': 'Akşam yemeği masasındaki sohbetler canlı, analitik ve ortaçağ dehşetinden tamamen uzaktı.', 'notes': 'free from terror: dehşetten uzak.'}, {'id': 180, 'text': 'Meanwhile, in his stone sanctuary, Sir Simon de Canterville was preparing his grand second assault.', 'translation': 'Bu esnada taş sığınağında Sir Simon de Canterville o büyük ikinci taarruzuna hazırlanıyordu.', 'notes': 'grand second assault: büyük ikinci taarruz.'}]}, {'page_no': 10, 'title': 'The Suit of Armor and the Midnight Collapse', 'tr_title': 'Şövalye Zırhı ve Gece Yarısı Çöküşü', 'vocab_focus': [('armor', 'zırh'), ('breastplate', 'göğüslük zırh'), ('clatter', 'tangırtı, şakırtı'), ('helmet', 'miğfer'), ('sprain', 'burkmak, incitmek'), ('lubricant', 'yağlayıcı'), ('crash', 'çarpma sesi, gürültü'), ('sanctuary', 'sığınak, korunak')], 'sentences': [{'id': 181, 'text': 'Sir Simon resolved that modern Americans could be conquered only through the majestic weight of medieval history.', 'translation': 'Sir Simon, modern Amerikalıların ancak ortaçağ tarihinin görkemli ağırlığıyla dize getirilebileceğine karar verdi.', 'notes': 'conquered through weight: ağırlığıyla dize getirilen.'}, {'id': 182, 'text': 'In the grand entrance hall stood a magnificent antique suit of steel armor worn by his grandfather at Agincourt.', 'translation': "Büyük giriş salonunda, dedesinin Agincourt Savaşı'nda giydiği muhteşem bir antika çelik zırh takımı duruyordu.", 'notes': 'antique suit of armor: antika zırh takımı.'}, {'id': 183, 'text': 'The ghost spent hours polishing the breastplate, greasing the visor, and admiring the gleaming plumed helmet.', 'translation': 'Hayalet göğüslüğü parlatarak, siperliği yağlayarak ve parıldayan tüylü miğfere hayranlıkla bakarak saatler harcadı.', 'notes': 'gleaming plumed helmet: parıldayan tüylü miğfer.'}, {'id': 184, 'text': 'On Sunday night, when the manor was silent and dark, he attempted to encase his transparent limbs in the steel.', 'translation': 'Pazar gecesi köşk sessiz ve karanlığa gömüldüğünde şeffaf uzuvlarını çeliğin içine sokmaya yeltendi.', 'notes': 'encase limbs: uzuvları içine sokmak.'}, {'id': 185, 'text': 'He managed to fasten the heavy greaves and don the cumbersome breastplate with immense spectral exertion.', 'translation': 'Muazzam bir hayaletsi çabayla ağır baldır zırhlarını bağlamayı ve hantal göğüslüğü kuşanmayı başardı.', 'notes': 'immense spectral exertion: muazzam hayaletsi çaba.'}, {'id': 186, 'text': 'However, the weight of the medieval metal proved utterly disastrous for his ethereal, immaterial frame.', 'translation': 'Ne var ki ortaçağ metalinin ağırlığı onun ruhani, maddesiz yapısı için tam anlamıyla feci bir sonuç doğurdu.', 'notes': 'ethereal frame: ruhani yapı/beden.'}, {'id': 187, 'text': 'As he stepped off the wooden pedestal, his knees buckled instantly beneath fifty pounds of solid steel.', 'translation': 'Ahşap kaideden aşağı adım attığı anda dizleri elli poundluk som çeliğin altında anında çözülüverdi.', 'notes': 'knees buckled instantly: dizleri anında çözüldü.'}, {'id': 188, 'text': 'A colossal crash and deafening metallic clatter resounded through the sleeping corridors of Canterville Chase!', 'translation': "Muazzam bir gümbürtü ve sağır edici bir madeni tangırtı Canterville Köşkü'nün uyuyan koridorlarında yankılandı!", 'notes': 'deafening metallic clatter: sağır edici madeni tangırtı.'}, {'id': 189, 'text': 'The noise was so tremendous that every member of the household was startled awake in their beds.', 'translation': 'Gürültü o kadar korkunçtu ki ev halkının her bir üyesi yataklarında irkilerek uyandı.', 'notes': 'startled awake: irkilerek uyandı.'}, {'id': 190, 'text': 'Mr. Otis leaped up, seized his revolver, and rushed down the broad oak staircase with Washington at his side.', 'translation': 'Bay Otis yerinden fırladı, altıpatlarını kaptı ve yanında Washington ile birlikte geniş meşe merdivenlerden aşağı koştu.', 'notes': 'broad oak staircase: geniş meşe merdiven.'}, {'id': 191, 'text': 'Upon reaching the stone landing, they beheld a most extraordinary and comical spectacle.', 'translation': 'Taş sahanlığa ulaştıklarında son derece olağandışı ve gülünç bir manzarayla karşılaştılar.', 'notes': 'comical spectacle: gülünç manzara.'}, {'id': 192, 'text': 'The antique suit of armor lay strewn across the stone flags in a disordered heap of iron plates.', 'translation': 'Antika zırh takımı taş döşemelerin üzerine düzensiz bir demir levhalar yığını halinde saçılmış yatıyordu.', 'notes': 'disordered heap: düzensiz yığın.'}, {'id': 193, 'text': 'Seated in a carved high-backed oak chair was the Canterville ghost, rubbing his ghostly knees with an expression of agony.', 'translation': 'Oymalı, yüksek arkalıklı bir meşe sandalyede oturan Canterville hayaleti ıstırap dolu bir ifadeyle hayaletsi dizlerini ovuyordu.', 'notes': 'expression of agony: ıstırap dolu ifade.'}, {'id': 194, 'text': 'He had severely bruised both shins and sprained his ethereal right ankle in the ignominious fall.', 'translation': 'Bu utanç verici düşüşte her iki kaval kemiğini fena halde berelemiş ve ruhani sağ ayak bileğini burkmuştu.', 'notes': 'ignominious fall: utanç verici düşüş.'}, {'id': 195, 'text': 'The twins had brought their pea-shooters and instantly discharged two stinging pellets of dried peas against his ribs.', 'translation': 'İkizler üfleme borularını getirmişlerdi ve anında kaburgalarına doğru iki can yakıcı kuru bezelye tanesi fırlattılar.', 'notes': 'pea-shooters: bezelye üfleme boruları.'}, {'id': 196, 'text': 'Mr. Otis leveled his revolver at the specter and commanded him to hold up his hands according to Californian etiquette.', 'translation': 'Bay Otis altıpatlarını hayalete doğrulttu ve Kaliforniya adabına uygun olarak ellerini kaldırmasını emretti.', 'notes': 'Californian etiquette: Kaliforniya görgüsü/adabı.'}, {'id': 197, 'text': 'The ghost started up with a wild screech of baffled rage and swept between them like a cold mist.', 'translation': 'Hayalet boşa çıkan öfkenin vahşi bir çığlığıyla yerinden sıçradı ve aralarından soğuk bir sis gibi süzüldü.', 'notes': 'baffled rage: boşa çıkan/engellenen öfke.'}, {'id': 198, 'text': "Extinguishing Washington's candle as he passed, he left them all in complete and pitch-black darkness.", 'translation': "Geçerken Washington'ın mumunu üfleyip söndürerek hepsini zifiri karanlık içinde bıraktı.", 'notes': 'pitch-black darkness: zifiri karanlık.'}, {'id': 199, 'text': 'On reaching the top of the stairs, he recovered himself and resolved to give his celebrated demonic laugh.', 'translation': 'Merdivenlerin tepesine ulaştığında kendini toparladı ve o meşhur şeytani kahkahasını atmaya karar verdi.', 'notes': 'celebrated demonic laugh: meşhur şeytani kahkaha.'}, {'id': 200, 'text': "That laugh had once turned Lord Raker's wig prematurely grey in a single night of horror!", 'translation': "O kahkaha bir keresinde tek bir dehşet gecesinde Lord Raker'ın peruğunu vaktinden önce ağartmıştı!", 'notes': 'prematurely grey: vaktinden önce ağarmış.'}]}, {'page_no': 11, 'title': "Mrs. Otis's Tincture and the Vanishing Laugh", 'tr_title': "Bayan Otis'in İlacı ve Kaybolan Kahkaha", 'vocab_focus': [('tincture', 'ilaç, tentür'), ('indigestion', 'hazımsızlık'), ('cordial', 'şurup, canlandırıcı içecek'), ('shrieking', 'çığlık atan'), ('hollow', 'kovuk, boşluk'), ('defiance', 'meydan okuma'), ('cavernous', 'mağara gibi, derin'), ('humiliation', 'aşağılanma')], 'sentences': [{'id': 201, 'text': 'He threw his spectral head back and uttered his most cavernous and terrifying demonic laugh.', 'translation': 'Hayaletsi başını geriye attı ve en derin, en korkunç şeytani kahkahasını kopardı.', 'notes': 'cavernous demonic laugh: mağara gibi derin şeytani kahkaha.'}, {'id': 202, 'text': 'The bloodcurdling sound echoed again and again through the vaulted arches of the ancient Tudor ceiling.', 'translation': 'Kan donduran ses, asırlık Tudor tavanının tonozlu kemerlerinde defalarca yankılandı.', 'notes': 'vaulted arches: tonozlu kemerler.'}, {'id': 203, 'text': 'He waited with immense pride to hear screams of terror from the bedrooms of the trembling inhabitants.', 'translation': 'Titreyen hane halkının yatak odalarından gelecek dehşet çığlıklarını duymak için muazzam bir gururla bekledi.', 'notes': 'screams of terror: dehşet çığlıkları.'}, {'id': 204, 'text': 'Hardly had the dreadful laughter died away when a bedroom door opened quietly on the landing.', 'translation': 'O korkunç kahkaha henüz dinmişti ki sahanlıktaki bir yatak odası kapısı usulca açıldı.', 'notes': 'hardly died away: henüz dinmişti ki.'}, {'id': 205, 'text': 'Out stepped Mrs. Otis, wearing a light blue dressing-gown and carrying a small bottle with a glass stopper.', 'translation': 'Dışarı açık mavi bir sabahlık giymiş ve cam tıpalı küçük bir şişe taşıyan Bayan Otis çıktı.', 'notes': 'glass stopper: cam tıpa.'}, {'id': 206, 'text': '"I am afraid you are far from well," said Mrs. Otis with calm and maternal concern.', 'translation': '"Korkarım hiç iyi değilsiniz," dedi Bayan Otis sakin ve anaç bir endişeyle.', 'notes': 'maternal concern: anaç endişe.'}, {'id': 207, 'text': '"I have brought you a bottle of Doctor Dobell\'s Tincture for indigestion and stomach complaints."', 'translation': '"Hazımsızlık ve mide şikayetleri için size bir şişe Doktor Dobell Tentürü getirdim."', 'notes': 'stomach complaints: mide şikayetleri.'}, {'id': 208, 'text': '"If it is indigestion that produces those dreadful noises, you will find this cordial an excellent remedy."', 'translation': '"Eğer bu korkunç sesleri çıkaran hazımsızlıksa, bu şurubun mükemmel bir deva olduğunu göreceksiniz."', 'notes': 'excellent remedy: mükemmel deva/ilaç.'}, {'id': 209, 'text': 'The ghost glared at her in speechless fury, feeling insulted to the very depths of his ancient soul.', 'translation': 'Hayalet asırlık ruhunun en derinlerine kadar hakarete uğramış hissederek dilsiz bir öfkeyle kadına dik dik baktı.', 'notes': 'speechless fury: nutku tutulmuş/dilsiz öfke.'}, {'id': 210, 'text': 'To have his celebrated supernatural laugh mistaken for a vulgar stomach ache was beyond all endurance!', 'translation': 'O meşhur doğaüstü kahkahasının sıradan bir mide ağrısıyla karıştırılması her türlü tahammülün ötesindeydi!', 'notes': 'beyond all endurance: her türlü tahammülün ötesinde.'}, {'id': 211, 'text': 'He contemplated turning himself into a great black dog, an exploit for which he had won high fame.', 'translation': 'Büyük siyah bir köpeğe dönüşmeyi düşündü; bu geçmişte kendisine büyük şöhret kazandırmış bir marifetti.', 'notes': 'won high fame: büyük şöhret kazandı.'}, {'id': 212, 'text': 'He had once frightened Lord Dumbleton into idiocy by barking at him from the interior of a wardrobe.', 'translation': "Bir zamanlar gardırobun içinden havlayarak Lord Dumbleton'ı ahmaklık derecesinde korkutmuştu.", 'notes': 'frightened into idiocy: ahmaklaşacak kadar korkuttu.'}, {'id': 213, 'text': 'However, the sound of approaching footsteps warned him that the troublesome twins were on the warpath.', 'translation': 'Fakat yaklaşan ayak sesleri belalı ikizlerin savaş yolunda olduğu konusunda onu uyardı.', 'notes': 'on the warpath: savaş yolunda/taarruzda.'}, {'id': 214, 'text': 'He heard them whispering excitedly about loading their pea-shooters with brass tacks and gravel.', 'translation': 'Üfleme borularını pirinç raptiyeler ve çakıl taşlarıyla doldurmak hakkında heyecanla fısıldaştıklarını duydu.', 'notes': 'brass tacks: pirinç raptiyeler.'}, {'id': 215, 'text': 'Discretion being the better part of spectral valor, he contented himself with becoming faintly phosphorescent.', 'translation': 'Tedbirli olmak hayaletsi cesaretin en erdemli yanı olduğundan hafifçe fosforlu bir ışıltıya bürünmekle yetindi.', 'notes': 'faintly phosphorescent: hafifçe fosforlu.'}, {'id': 216, 'text': 'He gave a melancholy, hollow groan as he dissolved into a thin column of grey smoke.', 'translation': 'Gri dumandan ince bir sütun halinde eriyip giderken kederli, boğuk bir inilti kopardı.', 'notes': 'column of smoke: duman sütunu.'}, {'id': 217, 'text': 'He vanished through the wainscoting just as the boys reached the top of the stairs brandishing cricket bats.', 'translation': 'Çocuklar kriket sopalarını sallayarak merdivenlerin tepesine tam ulaştıkları sırada ahşap kaplamanın içinden kayboldu.', 'notes': 'brandishing cricket bats: kriket sopalarını sallayan.'}, {'id': 218, 'text': 'On reaching his secret room, he broke down completely and buried his face in his cold hands.', 'translation': 'Gizli odasına ulaştığında tamamen yıkıldı ve yüzünü soğuk ellerine gömdü.', 'notes': 'broke down completely: tamamen yıkıldı/çöktü.'}, {'id': 219, 'text': 'The vulgarity of the mother and the gross materialism of the Minister were profoundly disgusting to him.', 'translation': "Annenin bayağılığı ve Elçi'nin kaba maddeciliği onun için son derece tiksindiriciydi.", 'notes': 'gross materialism: kaba maddecilik.'}, {'id': 220, 'text': 'Worst of all were the twins, whose constant practical jokes violated every rule of supernatural dignity.', 'translation': 'Hepsinden beteri ise bitmek bilmeyen eşek şakalarıyla doğaüstü vakuriyetin her kuralını çiğneyen ikizlerdi.', 'notes': 'practical jokes: eşek şakaları.'}]}, {'page_no': 12, 'title': "The Glorious Record of Sir Simon's Terrors", 'tr_title': "Sir Simon'ın Dehşet Saçan Şanlı Tarihi", 'vocab_focus': [('pedigree', 'soy ağacı, şecere'), ('exploits', 'kahramanlıklar, marifetler'), ('aristocrat', 'soylu, aristokrat'), ('paralyzed', 'felç olmuş, donakalmış'), ('rector', 'bölge papazı'), ('chambermaid', 'oda hizmetçisi'), ('reputation', 'itibar, şöhret'), ('historical', 'tarihi')], 'sentences': [{'id': 221, 'text': 'For several days after this encounter, his spectral nerves were thoroughly shattered.', 'translation': 'Bu karşılaşmanın ardından birkaç gün boyunca hayaletsi sinirleri tamamen harap oldu.', 'notes': 'thoroughly shattered: tamamen harap olmuş.'}, {'id': 222, 'text': 'He stayed in his secret chamber, reviewing his three-century record of terrifying triumphs across England.', 'translation': 'İngiltere çapındaki üç asırlık dehşet dolu zaferler sicilini gözden geçirerek gizli odasında kaldı.', 'notes': 'terrifying triumphs: dehşet dolu zaferler.'}, {'id': 223, 'text': 'He remembered with fond pride the beautiful Lady Stutfield, who always wore a black velvet band around her throat.', 'translation': "Boğazına daima siyah kadife bir kurdele takan güzel Leydi Stutfield'ı derin bir gururla hatırladı.", 'notes': 'black velvet band: siyah kadife kurdele/bant.'}, {'id': 224, 'text': 'She had drowned herself in the carp pond after he touched her bare neck with his icy skeleton fingers.', 'translation': 'Buz gibi iskelet parmaklarıyla çıplak boynuna dokunduktan sonra kadın sazan havuzunda kendini boğmuştu.', 'notes': 'drowned herself: kendini boğdu.'}, {'id': 225, 'text': 'He thought of the brave old general, Sir William Gull, who had fought fearlessly under the Duke of Marlborough.', 'translation': "Marlborough Dükü komutasında korkusuzca savaşmış olan cesur ihtiyar general Sir William Gull'u düşündü.", 'notes': 'fought fearlessly: korkusuzca savaştı.'}, {'id': 226, 'text': 'Sir William had suffered a fatal paralytic stroke when Sir Simon blew softly down the back of his neck.', 'translation': 'Sir Simon ensesine doğru usulca üflediğinde Sir William ölümcül bir felç geçirmişti.', 'notes': 'fatal paralytic stroke: ölümcül felç.'}, {'id': 227, 'text': 'He recalled the French cook, Monsieur Pierre, who had dropped dead over his pots upon seeing a bleeding heart.', 'translation': "Kanayan bir kalp görünce tencerelerinin üzerine düşüp ölen Fransız aşçı Mösyö Pierre'i anımsadı.", 'notes': 'dropped dead: düşüp öldü.'}, {'id': 228, 'text': 'He was the author of forty-seven documented nervous breakdowns among the highest peerage of the realm.', 'translation': 'Krallığın en yüksek soyluları arasında belgelenmiş kırk yedi sinir krizinin bizzat müellifiydi.', 'notes': 'highest peerage: en yüksek soylular sınıfı.'}, {'id': 229, 'text': 'Yet now, these wretched modern Americans treated him like an irritating nuisance or an amateur theatrical actor.', 'translation': 'Oysa şimdi bu sefil modern Amerikalılar ona sinir bozucu bir haşere veya amatör bir tiyatro oyuncusu gibi davranıyorlardı.', 'notes': 'irritating nuisance: sinir bozucu haşere/külfet.'}, {'id': 230, 'text': 'They offered him machine oil for his chains, suggested stomach medicines for his voice, and pelted him with peas!', 'translation': 'Zincirleri için ona makine yağı teklif ediyor, sesi için mide ilaçları öneriyor ve bezelye yağmuruna tutuyorlardı!', 'notes': 'pelted with peas: bezelye yağmuruna tuttu.'}, {'id': 231, 'text': 'It was beyond the endurance of any self-respecting aristocrat, living or dead.', 'translation': 'İster yaşayan ister ölü olsun, kendine saygısı olan hiçbir aristokratın tahammül edebileceği bir şey değildi bu.', 'notes': 'self-respecting aristocrat: kendine saygısı olan soylu.'}, {'id': 232, 'text': 'He decided that he would make one more grand, supreme effort to vindicate his ancient honor.', 'translation': 'Asırlık onurunu temize çıkarmak için bir büyük, yüce çaba daha göstermeye karar verdi.', 'notes': 'vindicate ancient honor: asırlık onurunu aklamak.'}, {'id': 233, 'text': 'He selected for his reappearance the terrifying disguise of "Dumb Daniel, or the Suicide\'s Skeleton".', 'translation': 'Yeniden ortaya çıkışı için "Dilsiz Daniel veya İntiharcının İskeleti" adlı korkunç kılığı seçti.', 'notes': 'terrifying disguise: korkunç kılık.'}, {'id': 234, 'text': 'In this character, he had once terrified young Lord Trevellyan into abandoning his wedding at the altar.', 'translation': "Bu roldeyken bir keresinde genç Lord Trevellyan'ı nikah masasındayken düğününü terk edecek kadar dehşete düşürmüştü.", 'notes': 'abandoning wedding: düğünü terk etmek.'}, {'id': 235, 'text': 'He spent three hours arranging his shroud, painting his skull with phosphor, and practicing his ghastly walk.', 'translation': 'Kefenini düzenleyerek, kafatasını fosforla boyayarak ve o korkunç yürüyüşünün provasını yaparak üç saat harcadı.', 'notes': 'ghastly walk: korkunç yürüyüş.'}, {'id': 236, 'text': "He planned to creep first into Washington's bedroom, where he would gibber at him from the foot of the bed.", 'translation': "Önce Washington'ın yatak odasına süzülmeyi ve yatağın ayakucundan ona anlamsız seslerle homurdanmayı planladı.", 'notes': 'gibber at him: ona anlamsız sesler çıkarmak.'}, {'id': 237, 'text': "Next, he would enter the Minister's chamber and place an icy, clammy hand upon Mrs. Otis's forehead.", 'translation': "Ardından Elçi'nin odasına girecek ve Bayan Otis'in alnına buz gibi, yapış yapış bir el koyacaktı.", 'notes': 'clammy hand: nemli/yapış yapış el.'}, {'id': 238, 'text': 'As for the twins, he would sit upon their chests and paralyze them with the nightmare of eternal suffocation.', 'translation': 'İkizlere gelince, göğüslerinin üzerine oturacak ve ebedi boğulma kabusuyla onları felç edecekti.', 'notes': 'eternal suffocation: ebedi boğulma.'}, {'id': 239, 'text': 'At a quarter past one in the morning, when the house was completely asleep, he glided out into the corridor.', 'translation': 'Gece saat biri çeyrek geçe, ev tamamen uykuya daldığında koridora doğru süzüldü.', 'notes': 'glided out: dışarı süzüldü.'}, {'id': 240, 'text': 'He felt confident that before dawn broke, the American interlopers would flee Canterville Chase forever.', 'translation': "Şafak sökmeden önce o Amerikalı davetsiz misafirlerin Canterville Köşkü'nden sonsuza dek kaçacağına emindi.", 'notes': 'American interlopers: Amerikalı davetsiz misafirler.'}]}, {'page_no': 13, 'title': 'The Counterfeit Phantom of the Twins', 'tr_title': 'İkizlerin Sahte Hayaleti', 'vocab_focus': [('counterfeit', 'sahte, taklit'), ('pumpkin', 'balkabağı'), ('hollow', 'oyuk, içi boş'), ('broomstick', 'süpürge sapı'), ('placard', 'pankart, yafta'), ('terrified', 'dehşete kapılmış'), ('retreat', 'geri çekilme'), ('apparition', 'hayalet, tayf')], 'sentences': [{'id': 241, 'text': 'The moon was hidden behind a bank of thick storm clouds, and the wind moaned softly through the galleries.', 'translation': 'Ay kalın bir fırtına bulutu kümesinin ardına saklanmıştı ve rüzgar galerilerde usulca inliyordu.', 'notes': 'bank of clouds: bulut kümesi.'}, {'id': 242, 'text': 'Sir Simon glided down the west corridor like an evil shadow, exulting in the silence of the night.', 'translation': 'Sir Simon gecenin sessizliğinden haz alarak uğursuz bir gölge gibi batı koridorunda süzüldü.', 'notes': 'exulting in silence: sessizlikten haz alan.'}, {'id': 243, 'text': "As he turned the dark corner leading to Washington's chamber, he suddenly stepped back with a muffled cry.", 'translation': "Washington'ın odasına çıkan karanlık köşeyi döndüğü anda boğuk bir çığlıkla aniden geriledi.", 'notes': 'muffled cry: boğuk çığlık.'}, {'id': 244, 'text': 'Right in front of him stood a monstrous, horrifying apparition of unparalleled frightfulness!', 'translation': 'Tam karşısında benzeri görülmemiş korkunçlukta devasa, dehşet verici bir hayalet dikiliyordu!', 'notes': 'unparalleled frightfulness: benzeri görülmemiş korkunçluk.'}, {'id': 245, 'text': 'Never having seen another phantom in his life, Sir Simon was struck with sudden, mortal panic.', 'translation': "Hayatında başka bir hayalet görmemiş olan Sir Simon'ı ani ve ölümcül bir panik çarptı.", 'notes': 'mortal panic: ölümcül panik.'}, {'id': 246, 'text': 'The creature had a bald, shining head, round and yellow as a melon, with hollow burning eyes.', 'translation': 'Yaratığın bir kavun gibi yuvarlak ve sarı, içi oyuk alev alev gözleri olan dazlak, parlayan bir kafası vardı.', 'notes': 'hollow burning eyes: oyuk alevli gözler.'}, {'id': 247, 'text': 'A hideous, gaping grin of red fire spread across its grotesque and featureless countenance.', 'translation': 'Ucube ve belirsiz çehresine kırmızı ateşten iğrenç, ayrık bir sırıtış yayılmıştı.', 'notes': 'featureless countenance: belirsiz/hatsız çehre.'}, {'id': 248, 'text': 'It was enveloped in vast flowing draperies of snow-white cloth that glowed in the darkness.', 'translation': 'Karanlıkta parıldayan kar beyazı kumaştan dökümlü geniş örtülere bürünmüştü.', 'notes': 'snow-white cloth: kar beyazı kumaş.'}, {'id': 249, 'text': 'In its right hand, it held an enormous curved scythe, the ancient emblem of Death itself.', 'translation': "Sağ elinde bizzat Ölüm'ün o kadim amblemi olan devasa eğri bir tırpan tutuyordu.", 'notes': 'curved scythe: eğri tırpan.'}, {'id': 250, 'text': 'Never had the Canterville ghost encountered a spectacle so utterly unnatural and horrifying.', 'translation': 'Canterville hayaleti hiçbir zaman bu kadar büsbütün doğa dışı ve dehşet verici bir manzarayla karşılaşmamıştı.', 'notes': 'utterly unnatural: büsbütün doğa dışı.'}, {'id': 251, 'text': 'Giving one terrified glance at the dreadful monster, he turned and fled in headlong flight down the hall.', 'translation': 'O korkunç canavara dehşet dolu tek bir bakış fırlatarak arkasını döndü ve salondan aşağı apar topar kaçtı.', 'notes': 'headlong flight: apar topar kaçış.'}, {'id': 252, 'text': 'He tripped over his long winding-sheet, dropped his rusty dagger, and plunged into his secret sanctuary.', 'translation': 'Uzun kefenine takılıp tökezledi, paslı hançerini düşürdü ve gizli sığınağına daldı.', 'notes': 'tripped over sheet: kefene takılıp tökezledi.'}, {'id': 253, 'text': 'He lay upon his dusty cot, trembling in every spectral limb, hiding his face beneath the moldy blankets.', 'translation': 'Tozlu kerevetine uzandı; her bir hayaletsi uzvu titreyerek yüzünü küflü battaniyelerin altına gizledi.', 'notes': 'moldy blankets: küflü battaniyeler.'}, {'id': 254, 'text': 'However, as the first rays of dawn touched the stone window, his ancient pride began to reawaken.', 'translation': 'Fakat şafağın ilk ışıkları taş pencereye vurduğunda asırlık gururu yeniden uyanmaya başladı.', 'notes': 'ancient pride reawakened: asırlık gurur yeniden uyandı.'}, {'id': 255, 'text': '"Why should I fear another ghost?" he muttered; "I am Sir Simon de Canterville, master of this chase!"', 'translation': '"Başka bir hayaletten neden korkacakmışım?" diye mırıldandı; "Ben bu köşkün efendisi Sir Simon de Canterville\'im!"', 'notes': 'master of this chase: bu köşkün efendisi.'}, {'id': 256, 'text': 'He resolved to go and fraternize with the stranger; two ghosts acting together could surely terrify the Americans.', 'translation': 'Gidip yabancıyla kardeşleşmeye karar verdi; birlikte hareket eden iki hayalet Amerikalıları muhakkak yıldırabilirdi.', 'notes': 'fraternize with stranger: yabancıyla kardeşleşmek/yakınlaşmak.'}, {'id': 257, 'text': 'Creeping back to the corridor in the early daylight, he approached the terrifying figure with cautious steps.', 'translation': 'Erken gün ışığında koridora geri süzülerek temkinli adımlarla o korkunç siluete yaklaştı.', 'notes': 'cautious steps: temkinli adımlar.'}, {'id': 258, 'text': 'He reached out a spectral hand to touch the white drapery, but the whole apparatus fell apart with a clatter!', 'translation': 'Beyaz örtüye dokunmak için hayaletsi bir el uzattı fakat bütün düzenek bir tangırtıyla dağılıverdi!', 'notes': 'apparatus fell apart: düzenek dağıldı.'}, {'id': 259, 'text': 'The head rolled across the floor: it was a hollowed pumpkin with a burnt-out candle end inside!', 'translation': 'Kafa yerde yuvarlandı: İçinde sönmüş bir mum ucu bulunan içi oyulmuş bir balkabağıydı bu!', 'notes': 'hollowed pumpkin: içi oyulmuş balkabağı.'}, {'id': 260, 'text': "Pinned to the broomstick was a placard: 'YE OTIS GHOSTE. YE ONLIE TRUE AND ORIGINAL SPOOK. BEWARE OF YE IMITATIONES!'", 'translation': "Süpürge sapına iliştirilmiş bir pankart vardı: 'OTIS HAYALETİ. YEGANE HAKİKİ VE ORİJİNAL HORTLAK. TAKLİTLERİNDEN SAKININ!'", 'notes': 'beware of imitations: taklitlerinden sakının.'}]}, {'page_no': 14, 'title': "Sir Simon's Nervous Breakdown and List Slippers", 'tr_title': "Sir Simon'ın Sinir Krizi ve Keçe Terlikleri", 'vocab_focus': [('exhausted', 'bitkin, tükenmiş'), ('nervous breakdown', 'sinir krizi'), ('list slippers', 'keçe tabanlı terlikler'), ('muffling', 'boğan, sesini kısan'), ('cautious', 'temkinli, dikkatli'), ('tripwire', 'tuzak teli'), ('ambush', 'pusu'), ('retreat', 'geri çekilmek')], 'sentences': [{'id': 261, 'text': "The truth flashed across Sir Simon's mind with sickening clarity: he had been tricked and made a fool of!", 'translation': "Gerçek, mide bulandırıcı bir berraklıkla Sir Simon'ın zihninde çaktı: Oyuna getirilmiş ve maskara edilmişti!", 'notes': 'made a fool of: maskara edildi.'}, {'id': 262, 'text': 'The vulgar American children had fashioned a ridiculous scarecrow out of a kitchen vegetable and a sheet!', 'translation': 'O kaba Amerikalı veletler bir mutfak sebzesi ve bir çarşaftan gülünç bir bostan korkuluğu yapmışlardı!', 'notes': 'ridiculous scarecrow: gülünç bostan korkuluğu.'}, {'id': 263, 'text': 'And he, Sir Simon de Canterville, whose ancestors had ridden with the Black Prince, had fled in terror from a turnip!', 'translation': 'Ve ataları Kara Prens ile at koşturmuş olan o Sir Simon de Canterville, bir şalgamdan dehşet içinde kaçmıştı!', 'notes': 'fled in terror: dehşet içinde kaçtı.'}, {'id': 264, 'text': 'A feeling of utter helplessness and profound nervous prostration overwhelmed the wretched spirit.', 'translation': 'Mutlak bir çaresizlik ve derin bir sinirsel tükenmişlik hissi o zavallı ruhu esir aldı.', 'notes': 'nervous prostration: sinirsel çöküntü/tükenmişlik.'}, {'id': 265, 'text': 'For the next three weeks, he did not leave his room except to renew the blood-stain in the library.', 'translation': 'Gelecek üç hafta boyunca kütüphanedeki kan lekesini yenilemek haricinde odasını hiç terk etmedi.', 'notes': 'did not leave his room: odasını terk etmedi.'}, {'id': 266, 'text': 'Even this duty he performed with listless dejection, having lost all artistic pride in his work.', 'translation': 'İşindeki bütün sanatsal gururu yitirdiğinden bu görevi dahi bezgin bir kederle yerine getirdi.', 'notes': 'listless dejection: bezgin keder.'}, {'id': 267, 'text': 'His nerves were so completely shattered that the slightest noise startled him into trembling convulsions.', 'translation': 'Sinirleri öylesine bütünüyle harap olmuştu ki en ufak bir ses bile onu titreme krizlerine sokmaya yetti.', 'notes': 'trembling convulsions: titreme krizleri.'}, {'id': 268, 'text': 'He adopted the extreme precaution of wearing soft list slippers to muffle his spectral footsteps completely.', 'translation': 'Hayaletsi ayak seslerini tamamen boğmak için yumuşak keçe tabanlı terlikler giyme gibi aşırı bir tedbire başvurdu.', 'notes': 'soft list slippers: yumuşak keçe terlikler.'}, {'id': 269, 'text': 'He was forced to use the Rising Sun Lubricator to oil his chains so they would not rattle in the dark.', 'translation': "Karanlıkta şakırdamasınlar diye zincirlerini yağlamak için Rising Sun Makine Yağı'nı kullanmak zorunda kaldı.", 'notes': 'forced to use: kullanmak zorunda kaldı.'}, {'id': 270, 'text': 'It was humiliating to use American grease, but he felt that survival took precedence over ancestral pride.', 'translation': 'Amerikan yağı kullanmak aşağılayıcıydı fakat hayatta kalmanın ata yadigarı gururdan önce geldiğini hissetti.', 'notes': 'took precedence: öncelik aldı.'}, {'id': 271, 'text': 'Yet despite all his humble precautions, the relentless twins gave him no quarter.', 'translation': 'Yine de bütün bu alçakgönüllü tedbirlerine rağmen amansız ikizler ona hiç aman vermedi.', 'notes': 'gave no quarter: aman vermedi.'}, {'id': 272, 'text': 'They stretched invisible strings across the corridors, tripping him up in the darkness at night.', 'translation': 'Geceleri karanlıkta tökezletip düşürerek koridorlar boyunca görünmez ipler gerdiler.', 'notes': 'stretched strings: ipler gerdiler.'}, {'id': 273, 'text': 'On one occasion, they constructed a buttered slide from the tapestry room to the top of the oak staircase.', 'translation': 'Bir keresinde halı kaplı odadan meşe merdivenlerin başına kadar tereyağlı bir kaydırak inşa ettiler.', 'notes': 'buttered slide: tereyağlı kaydırak.'}, {'id': 274, 'text': 'Sir Simon slipped on the grease and slid uncontrollably down twenty-five steps, injuring his dignity severely.', 'translation': 'Sir Simon yağın üzerinde kaydı ve haysiyetini ağır şekilde zedeleyerek yirmi beş basamak kontrolsüzce aşağı kaydı.', 'notes': 'injuring his dignity: haysiyetini zedeleyerek.'}, {'id': 275, 'text': 'Another evening, they arranged a heavy water-jug over his doorway, drenching him to the spectral skin.', 'translation': 'Başka bir akşam kapısının üzerine ağır bir su testisi yerleştirdiler ve hayaletsi tenine kadar onu sırılsıklam ettiler.', 'notes': 'drenching to the skin: tenine kadar sırılsıklam eden.'}, {'id': 276, 'text': 'The unfortunate phantom caught a severe spectral cold and could not appear for five consecutive days.', 'translation': 'Talihsiz hayalet ağır bir hayaletsi soğuk algınlığına yakalandı ve ardı ardına beş gün boyunca ortalıkta görünemedi.', 'notes': 'consecutive days: ardı ardına günler.'}, {'id': 277, 'text': 'He abandoned all thought of ever scaring the Otis family again, wishing only to be left in peaceful oblivion.', 'translation': 'Yalnızca huzurlu bir unutuluşa terk edilmeyi dileyerek Otis ailesini bir daha korkutmaya dair bütün düşünceleri terk etti.', 'notes': 'peaceful oblivion: huzurlu unutuluş.'}, {'id': 278, 'text': 'He even stopped renewing the blood-stain; the library floor remained clean for a whole week.', 'translation': 'Kan lekesini yenilemeyi dahi bıraktı; kütüphane zemini tam bir hafta boyunca tertemiz kaldı.', 'notes': 'stopped renewing: yenilemeyi bıraktı.'}, {'id': 279, 'text': 'Mr. Otis concluded that the ghost had departed, and wrote to Lord Canterville expressing his satisfaction.', 'translation': "Bay Otis hayaletin çekip gittiği sonucuna vardı ve memnuniyetini dile getiren bir mektubu Lord Canterville'e yazdı.", 'notes': 'expressing satisfaction: memnuniyetini dile getiren.'}, {'id': 280, 'text': 'Yet the sorrowful specter was still haunting the house, broken in spirit and yearning for eternal rest.', 'translation': 'Oysa o kederli hortlak ruhu paramparça ve ebedi bir huzurun hasretiyle hâlâ evin içinde dolanıyordu.', 'notes': 'yearning for rest: huzurun hasretiyle yanan.'}]}, {'page_no': 15, 'title': 'Virginia Finds the Weeping Phantom', 'tr_title': 'Virginia Ağlayan Hayaleti Buluyor', 'vocab_focus': [('tapestry', 'duvar halısı'), ('embroidery', 'nakış, dikiş'), ('compassion', 'merhamet, şefkat'), ('solitude', 'yalnızlık, inziva'), ('weeping', 'ağlayan, gözyaşı döken'), ('forlorn', 'kimsesiz, perişan'), ('window', 'pencere'), ('sympathy', 'sempati, duygudaşlık')], 'sentences': [{'id': 281, 'text': 'A few days later, Miss Virginia Otis was riding her pony in Brockley lanes accompanied by the young Duke of Cheshire.', 'translation': 'Birkaç gün sonra Bayan Virginia Otis, genç Cheshire Dükü eşliğinde Brockley yollarında midillisine biniyordu.', 'notes': 'riding her pony: midillisine binen.'}, {'id': 282, 'text': 'While leaping a prickly hawthorn hedge, she accidentally tore her riding habit severely across the sleeve.', 'translation': 'Dikenli bir alıç çitinin üzerinden atlarken kazara binici giysisinin kolunu boydan boya fena halde yırttı.', 'notes': 'riding habit: binici giysisi.'}, {'id': 283, 'text': 'She returned to Canterville Chase by the back way so that her mother would not notice the torn cloth.', 'translation': "Annesi yırtık kumaşı fark etmesin diye arka yoldan Canterville Köşkü'ne geri döndü.", 'notes': 'by the back way: arka yoldan.'}, {'id': 284, 'text': 'Running upstairs to the Tapestry Room to fetch a needle and thread, she found the heavy door slightly ajar.', 'translation': "Bir iğne ve iplik almak için koşa koşa yukarıdaki Halı Odası'na çıktığında ağır kapıyı hafifçe aralık buldu.", 'notes': 'slightly ajar: hafifçe aralık.'}, {'id': 285, 'text': "Thinking it was her mother's French maid who often sat there with embroidery, she pushed the door gently open.", 'translation': 'Genellikle orada nakış işleyerek oturan annesinin Fransız hizmetçisi olduğunu sanarak kapıyı nazikçe itip açtı.', 'notes': 'pushed gently open: nazikçe itip açtı.'}, {'id': 286, 'text': 'To her immense surprise, she saw an elderly man sitting quietly by the tall, mullioned window.', 'translation': 'Büyük bir şaşkınlıkla, yüksek ve dikmeli pencerenin kenarında sessizce oturan yaşlı bir adam gördü.', 'notes': 'mullioned window: dikmeli/bölmeli pencere.'}, {'id': 287, 'text': 'His head was leaning heavily upon his hand, and his whole attitude was one of extreme, forlorn depression.', 'translation': 'Başı ağır bir biçimde eline yaslanmıştı ve tüm duruşu aşırı, kimsesiz bir çökkünlüğü yansıtıyordu.', 'notes': 'forlorn depression: kimsesiz çökkünlük/keder.'}, {'id': 288, 'text': 'He was looking out upon the golden autumn trees, gazing wistfully at the yellow leaves dancing on the wind.', 'translation': 'Altın sarısı sonbahar ağaçlarına bakıyor, rüzgarda dans eden sarı yaprakları hüzünle seyrediyordu.', 'notes': 'gazing wistfully: hüzünle seyreden.'}, {'id': 289, 'text': 'His ragged Tudor garments hung loosely from his emaciated frame, and his matted grey hair fell over his collar.', 'translation': 'Eski püskü Tudor giysileri bir deri bir kemik kalmış bedeninden bolca sarkıyor, keçeleşmiş gri saçları yakasına dökülüyordu.', 'notes': 'emaciated frame: bir deri bir kemik beden.'}, {'id': 290, 'text': 'Virginia recognized the Canterville ghost instantly, but her gentle heart was filled with pity rather than fear.', 'translation': 'Virginia Canterville hayaletini hemen tanıdı fakat o nazik yüreği korku yerine merhametle doldu.', 'notes': 'filled with pity: merhametle doldu.'}, {'id': 291, 'text': 'Her first natural impulse had been to run away and lock herself safely in her bedchamber.', 'translation': 'İlk doğal dürtüsü kaçıp kendini güvenle yatak odasına kilitlemek olmuştu.', 'notes': 'natural impulse: doğal dürtü.'}, {'id': 292, 'text': 'Yet looking at his stooped shoulders and trembling hands, she felt a profound surge of youthful compassion.', 'translation': 'Yine de onun kamburlaşmış omuzlarına ve titreyen ellerine bakınca içinde gençliğe özgü derin bir şefkat dalgası hissetti.', 'notes': 'surge of compassion: şefkat dalgası.'}, {'id': 293, 'text': 'She stepped softly into the room, her light footsteps making no sound upon the faded carpet.', 'translation': 'Hafif ayak sesleri solgun halının üzerinde hiç ses çıkarmayarak odaya doğru usulca adım attı.', 'notes': 'faded carpet: solgun halı.'}, {'id': 294, 'text': '"I am so sorry for you," said Virginia in her sweet, musical voice; "my brothers are going back to Eton tomorrow."', 'translation': '"Sizin adınıza çok üzgünüm," dedi Virginia o tatlı, ahenkli sesiyle; "erkek kardeşlerim yarın Eton Koleji\'ne dönüyorlar."', 'notes': 'sweet musical voice: tatlı ahenkli ses.'}, {'id': 295, 'text': '"And then, if you behave yourself properly, no one will ever annoy you again."', 'translation': '"Ve ondan sonra, eğer uslu durursanız hiç kimse sizi bir daha asla rahatsız etmeyecektir."', 'notes': 'behave properly: uslu durmak/düzgün davranmak.'}, {'id': 296, 'text': 'The ghost started violently, turning around with a look of utter amazement upon his wrinkled face.', 'translation': 'Hayalet şiddetle irkildi; kırışık yüzünde katıksız bir hayret ifadesiyle arkasına döndü.', 'notes': 'look of amazement: hayret ifadesi.'}, {'id': 297, 'text': '"It is absurd asking me to behave myself," he answered, glaring at the pretty young girl.', 'translation': '"Benden uslu durmamı istemek saçmalıktır," diye yanıtladı, o sevimli genç kıza dik dik bakarak.', 'notes': 'absurd asking me: benden istemek saçmalık.'}, {'id': 298, 'text': '"Quite absurd! I must rattle my chains, and groan through keyholes, and walk about at night."', 'translation': '"Büsbütün saçmalık! Zincirlerimi şakırdatmalı, anahtar deliklerinden inlemeli ve geceleri etrafta dolaşmalıyım."', 'notes': 'quite absurd: büsbütün saçmalık.'}, {'id': 299, 'text': '"It is my only reason for existing; it is the sacred duty of an ancestral family ghost!"', 'translation': '"Var olmamın yegane sebebi budur; soylu bir aile hayaletinin kutsal vazifesidir bu!"', 'notes': 'reason for existing: varoluş sebebi.'}, {'id': 300, 'text': '"It is no reason at all for existing," said Virginia gravely, "and you know you have been very wicked."', 'translation': '"Var olmak için bu hiçbir sebep teşkil etmez," dedi Virginia ciddiyetle, "ve çok kötü biri olduğunuzu pekala biliyorsunuz."', 'notes': 'said gravely: ciddiyetle söyledi.'}]}, {'page_no': 16, 'title': "The Ghost's Confession and the Stolen Paints", 'tr_title': 'Hayaletin İtirafı ve Çalınan Boyalar', 'vocab_focus': [('confession', 'itiraf'), ('starving', 'açlıktan ölmek'), ('starved', 'aç bırakılmış'), ('wicked', 'kötü, günahkar'), ('starvation', 'açlık, açlıktan ölme'), ('box of paints', 'boya kutusu'), ('repentance', 'pişmanlık, tövbe'), ('captive', 'tutsak, esir')], 'sentences': [{'id': 301, 'text': '"Mrs. Umney told us the first day we arrived here that you murdered your wife," Virginia continued bravely.', 'translation': '"Buraya geldiğimiz ilk gün Bayan Umney bize karınızı öldürdüğünüzü söyledi," diye cesurca devam etti Virginia.', 'notes': 'murdered your wife: karınızı öldürdünüz.'}, {'id': 302, 'text': '"Well, I quite admit it," said the ghost petulantly, "but it was a purely family matter, and concerned no one else."', 'translation': '"Eh, bunu tamamen kabul ediyorum," dedi hayalet hırçınca, "fakat bu sırf bir aile meselesiydi ve başka kimseyi ilgilendirmezdi."', 'notes': 'purely family matter: sırf aile meselesi.'}, {'id': 303, 'text': '"It is very wrong to kill anyone," declared Virginia, who had strong moral convictions.', 'translation': '"Herhangi birini öldürmek son derece yanlıştır," diye bildirdi güçlü ahlaki inançları olan Virginia.', 'notes': 'moral convictions: ahlaki inançlar.'}, {'id': 304, 'text': '"Oh, I hate the cheap severity of abstract ethics!" the phantom cried with philosophical indignation.', 'translation': '"Ah, soyut ahlak kurallarının o ucuz katılığından nefret ediyorum!" diye felsefi bir hiddetle haykırdı hortlak.', 'notes': 'abstract ethics: soyut ahlak kuralları.'}, {'id': 305, 'text': '"My wife was very plain, she never could starch my ruffs properly, and she knew nothing about cookery!"', 'translation': '"Karım son derece gösterişsizdi, yakalıklarımı asla düzgünce kolalayamazdı ve yemek pişirmekten zerre kadar anlamazdı!"', 'notes': 'starch my ruffs: yakalıklarımı kolalamak.'}, {'id': 306, 'text': '"Why, there was a buck I had shot in Hogley Woods, and she served it up tough and burnt to a cinder!"', 'translation': '"Düşün bir, Hogley Koruluğu\'nda vurduğum bir erkek geyik vardı, onu kömür gibi yanmış ve kayış gibi sert servis etti!"', 'notes': 'burnt to a cinder: kömür gibi yanmış.'}, {'id': 307, 'text': '"However, it is no use discussing that now; it is all over and done with centuries ago."', 'translation': '"Ne var ki bunu şimdi tartışmanın hiçbir faydası yok; hepsi asırlar önce bitti gitti."', 'notes': 'over and done with: bitti gitti.'}, {'id': 308, 'text': '"Only I don\'t think it was at all nice of her nine brothers to starve me to death in a dark cellar!"', 'translation': '"Yalnızca dokuz erkek kardeşinin beni karanlık bir mahzende açlıktan öldürmesinin hiç de hoş bir hareket olduğunu sanmıyorum!"', 'notes': 'starve to death: açlıktan öldürmek.'}, {'id': 309, 'text': 'Virginia\'s eyes opened wide in horror: "Starve you to death? Oh, Mr. Ghost, I mean Sir Simon, were you hungry?"', 'translation': 'Virginia\'nın gözleri dehşetle ardına kadar açıldı: "Sizi açlıktan mı öldürdüler? Ah Bay Hayalet, yani Sir Simon, aç mı kaldınız?"', 'notes': 'eyes opened wide: gözleri fal taşı gibi açıldı.'}, {'id': 310, 'text': '"I have not eaten anything for three hundred years," the ghost answered mournfully, gazing into her compassionate face.', 'translation': '"Üç yüz yıldır hiçbir şey yemedim," diye yaslı bir sesle yanıtladı hayalet, kızın şefkat dolu yüzüne bakarak.', 'notes': 'answered mournfully: yaslı bir sesle yanıtladı.'}, {'id': 311, 'text': '"I have a sandwich in my pocket if you would like it," Virginia offered gently, reaching for her riding bag.', 'translation': '"İsterseniz cebimde bir sandviç var," diye nazikçe teklif etti Virginia, binici çantasına uzanarak.', 'notes': 'offered gently: nazikçe teklif etti.'}, {'id': 312, 'text': '"No, thank you, gentle maiden; spirits cannot partake of earthly food, though your kindness touches my weary soul."', 'translation': '"Hayır teşekkür ederim kibar genç kız; ruhlar dünyevi yiyeceklerden yiyemezler, gerçi nezaketiniz yorgun ruhuma dokundu."', 'notes': 'earthly food: dünyevi yiyecek.'}, {'id': 313, 'text': '"Besides, it is very nice of you, much nicer than the rest of your rude, vulgar family."', 'translation': '"Hem bu davranışınız çok hoş, o kaba ve bayağı ailenizin geri kalanından katbekat daha güzel."', 'notes': 'rude vulgar family: kaba bayağı aile.'}, {'id': 314, 'text': '"Stop!" cried Virginia, stamping her foot indignantly; "It is you who are rude, and horrid, and vulgar!"', 'translation': '"Durun!" diye haykırdı Virginia, ayağını öfkeyle yere vurarak; "Asıl kaba, korkunç ve bayağı olan sizsiniz!"', 'notes': 'stamping her foot: ayağını yere vurarak.'}, {'id': 315, 'text': '"And as for dishonesty, you know you stole the paints out of my box to renew that ridiculous stain on the floor!"', 'translation': '"Ve sahtekarlığa gelince, yerdeki o gülünç lekeyi tazelemek için kutumdan boyaları çaldığınızı pekala biliyorsunuz!"', 'notes': 'stole the paints: boyaları çaldınız.'}, {'id': 316, 'text': '"You took all my best vermilion, and when that was gone, you took my emerald green and my ultramarine blue!"', 'translation': '"En iyi nar kırmızı boyamı aldınız ve o bitince zümrüt yeşilimi ve lacivertimi aldınız!"', 'notes': 'ultramarine blue: lacivert, koyu mavi.'}, {'id': 317, 'text': '"I never told on you, though it made me very angry to see an emerald green blood-stain in an English drawing room!"', 'translation': '"İngiliz salonunda zümrüt yeşili bir kan lekesi görmek beni çok öfkelendirse de sizi asla ele vermedim!"', 'notes': 'never told on you: sizi hiç ele vermedim.'}, {'id': 318, 'text': 'The ghost hung his head in shame: "Well, really, what could I do? Real blood is so very difficult to procure nowadays."', 'translation': 'Hayalet utanç içinde başını öne eğdi: "Şey, sahiden ne yapabilirdim ki? Günümüzde gerçek kan bulmak öylesine zor ki."', 'notes': 'hung head in shame: utançla başını öne eğdi.'}, {'id': 319, 'text': '"And since your brother began using Pinkerton, I had to take whatever colors were available in your bedroom."', 'translation': '"Ve kardeşiniz Pinkerton kullanmaya başladığından beri, yatak odanızda hangi renkler varsa onları almak zorundaydım."', 'notes': 'whatever colors available: hangi renkler varsa.'}, {'id': 320, 'text': '"As for the green, the Cantervilles have always had green blood when fighting for the Crown; it was a matter of family heraldry."', 'translation': '"Yeşile gelince, Canterville\'ler Taht için savaşırken her zaman yeşil kana sahip olmuşlardır; bu bir aile armacılığı meselesiydi."', 'notes': 'family heraldry: aile armacılığı/şeceresi.'}]}, {'page_no': 17, 'title': 'The Yearning for Eternal Rest', 'tr_title': 'Ebedi Huzur Hasreti', 'vocab_focus': [('slumber', 'uyku, uyuklama'), ('weary', 'yorgun, bitkin'), ('cemetery', 'mezarlık'), ('yew tree', 'porsuk ağacı'), ('silence', 'sessizlik, sükunet'), ('repose', 'istirahat, huzur'), ('forgiveness', 'bağışlanma, af'), ('longing', 'özlem, hasret')], 'sentences': [{'id': 321, 'text': '"I don\'t think you are nearly so bad as you make yourself out to be," said Virginia softly.', 'translation': '"Kendinizi gösterdiğiniz kadar fena biri olduğunuzu hiç sanmıyorum," dedi Virginia usulca.', 'notes': 'make yourself out: kendini öyle göstermek.'}, {'id': 322, 'text': 'The ghost shook his head with an expression of infinite melancholy: "You do not understand, gentle child."', 'translation': 'Hayalet sonsuz bir hüzün ifadesiyle başını salladı: "Anlamıyorsunuz kibar çocuk."', 'notes': 'infinite melancholy: sonsuz hüzün.'}, {'id': 323, 'text': '"I am so terribly lonely and unhappy; I really don\'t know what to do with myself."', 'translation': '"Öylesine korkunç derecede yalnız ve mutsuzum ki; kendimle ne yapacağımı gerçekten bilmiyorum."', 'notes': 'terribly lonely: korkunç derecede yalnız.'}, {'id': 324, 'text': '"I want to go to sleep, but I have not slept for three hundred long, agonizing years."', 'translation': '"Uyumak istiyorum fakat üç yüz uzun, kahredici yıldır bir an bile uyumadım."', 'notes': 'three hundred agonizing years: üç yüz kahredici yıl.'}, {'id': 325, 'text': '"Poor, poor Ghost!" murmured Virginia, tears springing to her sweet blue eyes; "is there no place where you can sleep?"', 'translation': '"Zavallı, talihsiz Hayalet!" diye mırıldandı Virginia, tatlı mavi gözlerine yaşlar hücum ederek; "uyuyabileceğiniz hiçbir yer yok mu?"', 'notes': 'tears springing to eyes: gözlerine yaşlar hücum eden.'}, {'id': 326, 'text': '"Far away beyond the pine-woods," he answered in a low, musical voice, "there is a little churchyard."', 'translation': '"Çam korularının çok ötesinde," diye yanıtladı alçak, ahenkli bir sesle, "küçük bir kilise mezarlığı vardır."', 'notes': 'little churchyard: küçük kilise mezarlığı.'}, {'id': 327, 'text': '"There the grass grows long and deep, the great yew-trees wave their dark branches, and the white hemlock blossoms."', 'translation': '"Orada çimenler gür ve derin büyür, ulu porsuk ağaçları karanlık dallarını sallar ve beyaz baldıranlar çiçek açar."', 'notes': 'yew-trees: porsuk ağaçları.'}, {'id': 328, 'text': '"There the nightingale sings all night long in the cold silver moonlight."', 'translation': '"Orada bülbül soğuk gümüş ay ışığında bütün gece boyunca şakır durur."', 'notes': 'nightingale sings: bülbül şakır.'}, {'id': 329, 'text': '"All night long he sings, and the cold crystal moon looks down, and the ancient yew-tree spreads its shadowy arms."', 'translation': '"Bütün gece şakır, soğuk kristal ay aşağıya bakar ve kadim porsuk ağacı gölgeli kollarını uzatır."', 'notes': 'shadowy arms: gölgeli kollar.'}, {'id': 330, 'text': "Virginia's eyes grew misty with tears as she listened to his poetic description of the grave.", 'translation': "Mezarın bu şiirsel tasvirini dinlerken Virginia'nın gözleri yaşlarla buğulandı.", 'notes': 'misty with tears: yaşlarla buğulanmış.'}, {'id': 331, 'text': '"You mean the Garden of Death," she whispered softly, her fingers tightening around her handkerchief.', 'translation': '"Ölüm Bahçesi\'ni kastediyorsunuz," diye usulca fısıldadı kız, parmakları mendilini sıkarak.', 'notes': 'Garden of Death: Ölüm Bahçesi.'}, {'id': 332, 'text': '"Yes, Death! Death must be so beautiful, so silent, so calm," the phantom sighed yearningly.', 'translation': '"Evet, Ölüm! Ölüm öyle güzel, öyle sessiz, öyle sakin olmalı ki," diye hasretle iç çekti hayalet.', 'notes': 'sighed yearningly: hasretle iç çekti.'}, {'id': 333, 'text': '"To lie in the soft brown earth, with the grasses waving above one\'s head, and listen to the eternal silence."', 'translation': '"Yumuşak kahverengi toprakta, başının üzerinde dalgalanan çimenlerle yatmak ve o ebedi sessizliği dinlemek."', 'notes': 'eternal silence: ebedi sessizlik.'}, {'id': 334, 'text': '"To have no yesterday, and no tomorrow; to forget time, to forgive life, to be forever at peace."', 'translation': '"Ne dününün ne de yarınının olması; zamanı unutmak, hayatı affetmek, sonsuza dek huzur içinde olmak."', 'notes': 'forever at peace: sonsuza dek huzur içinde.'}, {'id': 335, 'text': '"You can help me; you can open the marble doors of Death for me, for Love is always with you, and Love is stronger than Death."', 'translation': '"Bana yardım edebilirsiniz; benim için Ölüm\'ün mermer kapılarını açabilirsiniz, zira Sevgi daima sizinledir ve Sevgi Ölüm\'den güçlüdür."', 'notes': "Love is stronger than Death: Sevgi Ölüm'den güçlüdür."}, {'id': 336, 'text': 'Virginia shivered, feeling a sudden icy chill run through the warm summer air of the room.', 'translation': 'Virginia ürperdi; odanın ılık yaz havasının içinden ani, buz gibi bir ayazın geçtiğini hissetti.', 'notes': 'shivered: ürperdi.'}, {'id': 337, 'text': '"What can I do?" she asked in a trembling voice; "I am only a young and powerless girl."', 'translation': '"Ben ne yapabilirim ki?" diye sordu titreyen bir sesle; "Ben yalnızca genç ve güçsüz bir kızım."', 'notes': 'trembling voice: titreyen ses.'}, {'id': 338, 'text': '"You have a pure, innocent heart, untouched by sin or worldliness," Sir Simon replied tenderly.', 'translation': '"Günah veya dünyevilikle lekelenmemiş saf, masum bir kalbiniz var," diye şefkatle yanıtladı Sir Simon.', 'notes': 'untouched by sin: günahla lekelenmemiş.'}, {'id': 339, 'text': '"The dark powers will listen to your prayers when they turn away in deaf anger from my guilty soul."', 'translation': '"Karanlık güçler benim günahkar ruhumdan sağır bir öfkeyle yüz çevirirken sizin dualarınıza kulak vereceklerdir."', 'notes': 'deaf anger: sağır bir öfke.'}, {'id': 340, 'text': '"Have you ever read the ancient Gothic prophecy written upon the library window?"', 'translation': '"Kütüphane penceresine yazılmış o kadim Gotik kehaneti hiç okudunuz mu?"', 'notes': 'ancient Gothic prophecy: kadim Gotik kehanet.'}]}, {'page_no': 18, 'title': 'The Ancient Prophecy on the Library Window', 'tr_title': 'Kütüphane Penceresindeki Kadim Kehanet', 'vocab_focus': [('prophecy', 'kehanet'), ('inscription', 'yazıt, kitabe'), ('rhymes', 'kafiyeler, manzum mısralar'), ('maiden', 'bakire kız, genç kız'), ('weeping', 'ağlama, gözyaşı dökme'), ('barren', 'kısır, kurumuş, çorak'), ('almond tree', 'badem ağacı'), ('blessing', 'kutsama, lütuf')], 'sentences': [{'id': 341, 'text': '"Oh, often!" cried Virginia, looking up at him; "the strange verses written in ancient gold letters on the glass!"', 'translation': '"Ah, sıklıkla!" diye haykırdı Virginia başını ona kaldırarak; "camın üzerindeki antik altın harflerle yazılmış o tuhaf mısralar!"', 'notes': 'ancient gold letters: antik altın harfler.'}, {'id': 342, 'text': '"They are very curious, but I could never quite understand what they really mean."', 'translation': '"Çok tuhaflar fakat gerçekte ne anlama geldiklerini hiçbir zaman tam olarak anlayamadım."', 'notes': 'could never understand: asla anlayamadım.'}, {'id': 343, 'text': '"There are only six rhyming lines, but the words sound so mysterious and solemn."', 'translation': '"Yalnızca kafiyeli altı mısradan ibaret fakat kelimeler öylesine esrarengiz ve vakur tınlıyor ki."', 'notes': 'mysterious and solemn: esrarengiz ve vakur.'}, {'id': 344, 'text': '"Recite them to me, gentle Virginia," said the phantom, closing his tired eyes in concentration.', 'translation': '"Onları bana ezbere oku kibar Virginia," dedi hayalet, yorgun gözlerini odaklanarak kapatarak.', 'notes': 'recite them: onları ezbere oku.'}, {'id': 345, 'text': 'Virginia folded her hands together and repeated the ancient prophecy with clear, musical reverence:', 'translation': 'Virginia ellerini birleştirdi ve berrak, ahenkli bir hürmetle kadim kehaneti tekrarladı:', 'notes': 'musical reverence: ahenkli hürmet.'}, {'id': 346, 'text': '"When a golden girl can win prayer from out the lips of sin,"', 'translation': '"Altın sarısı bir kız günahkar dudaklardan duayı koparabildiğinde,"', 'notes': 'golden girl: altın saçlı/değerli kız.'}, {'id': 347, 'text': '"When the barren almond bears, and a little child gives tears,"', 'translation': '"Kurumuş badem ağacı meyve verdiğinde ve küçük bir çocuk gözyaşı döktüğünde,"', 'notes': 'barren almond bears: kurumuş badem meyve/çiçek verir.'}, {'id': 348, 'text': '"Then shall all the house be still, and peace come to Canterville."', 'translation': '"O zaman bütün ev huzura kavuşacak ve Canterville\'e barış gelecek."', 'notes': "peace come to Canterville: Canterville'e barış gelir."}, {'id': 349, 'text': "A faint, tender smile touched the ghost's pale lips as the sacred words echoed in the room.", 'translation': 'Kutsal kelimeler odada yankılanırken solgun dudaklarına hafif, şefkatli bir tebessüm dokundu.', 'notes': 'tender smile: şefkatli tebessüm.'}, {'id': 350, 'text': '"The prophecy means that you must weep for me for my sins, because I have no tears left to shed,"', 'translation': '"Bu kehanet, dökecek hiçbir gözyaşım kalmadığı için benim günahlarıma senin ağlaman gerektiği anlamına geliyor,"', 'notes': 'no tears left to shed: dökecek gözyaşı kalmamış.'}, {'id': 351, 'text': '"And you must pray with me for my soul, because I have no faith left in my withered heart."', 'translation': '"Ve kurumuş kalbimde hiç inanç kalmadığı için benim ruhum için benimle birlikte dua etmelisin."', 'notes': 'no faith left: hiç inanç kalmamış.'}, {'id': 352, 'text': '"And then, if you have been always sweet, and good, and gentle, the Angel of Death will have mercy upon me."', 'translation': '"Ve o zaman, eğer her zaman tatlı, iyi ve nazik biri olduysan, Ölüm Meleği bana merhamet gösterecektir."', 'notes': 'Angel of Death: Ölüm Meleği.'}, {'id': 353, 'text': '"You will see fearful shapes in the darkness, and wicked voices will whisper terrible things in your ear,"', 'translation': '"Karanlıkta korkunç şekiller göreceksin ve kötü sesler kulağına dehşetli şeyler fısıldayacak,"', 'notes': 'fearful shapes: korkunç şekiller.'}, {'id': 354, 'text': '"But they shall not harm you, for against the purity of a little child the powers of Hell cannot prevail."', 'translation': '"Fakat sana zarar veremezler zira küçük bir çocuğun masumiyeti karşısında Cehennemin güçleri galebe çalamaz."', 'notes': 'cannot prevail: galebe çalamaz/üstün gelemez.'}, {'id': 355, 'text': 'Virginia made no answer, but her heart beat rapidly with a mixture of terror and sublime resolve.', 'translation': 'Virginia hiçbir cevap vermedi fakat kalbi dehşet ve yüce bir kararlılığın karışımıyla hızla çarpıyordu.', 'notes': 'sublime resolve: yüce kararlılık.'}, {'id': 356, 'text': 'She looked at the miserable old phantom whose tragic punishment had lasted for three hundred years.', 'translation': 'Trajik cezası üç yüz yıldır süregelen o perişan ihtiyar hayalete baktı.', 'notes': 'tragic punishment: trajik ceza.'}, {'id': 357, 'text': 'She knew that her parents and brothers would never understand the spiritual mystery of this moment.', 'translation': 'Anne babasının ve erkek kardeşlerinin bu anın manevi gizemini asla anlayamayacağını biliyordu.', 'notes': 'spiritual mystery: manevi gizem.'}, {'id': 358, 'text': 'They were modern, practical people who believed only in detergents, machine oils, and balance sheets.', 'translation': 'Onlar yalnızca deterjanlara, makine yağlarına ve bilanço tablolarına inanan modern, pratik insanlardı.', 'notes': 'balance sheets: bilanço tabloları.'}, {'id': 359, 'text': 'Yet she, in her youthful innocence, recognized a call to divine mercy that transcended all logic.', 'translation': 'Oysa o, gençlik masumiyeti içinde her türlü mantığı aşan ilahi bir merhamet çağrısını idrak etmişti.', 'notes': 'divine mercy: ilahi merhamet.'}, {'id': 360, 'text': "She took a deep breath, raised her head, and met Sir Simon's pleading gaze with serene bravery.", 'translation': "Derin bir nefes aldı, başını kaldırdı ve Sir Simon'ın yalvaran bakışlarını dingin bir cesaretle karşıladı.", 'notes': 'serene bravery: dingin cesaret.'}]}, {'page_no': 19, 'title': "Virginia's Choice of Mercy and Love", 'tr_title': "Virginia'nın Merhamet ve Sevgi Tercihi", 'vocab_focus': [('choice', 'seçim, tercih'), ('courage', 'cesaret'), ('threshold', 'eşik'), ('darkness', 'karanlık'), ('phantom', 'hayalet'), ('trembling', 'titreyen'), ('portal', 'kapı, geçit'), ('underworld', 'yeraltı dünyası')], 'sentences': [{'id': 361, 'text': '"I am not afraid," Virginia said simply, rising to her feet and standing before the phantom.', 'translation': '"Korkmuyorum," dedi Virginia sadece, ayağa kalkıp hayaletin önünde dikilerek.', 'notes': 'rising to feet: ayağa kalkan.'}, {'id': 362, 'text': '"I will ask the Angel of Death to have mercy on you, and I will pray with you until peace is won."', 'translation': '"Ölüm Meleği\'nden size merhamet etmesini dileyeceğim ve huzur kazanılana kadar sizinle birlikte dua edeceğim."', 'notes': 'peace is won: huzur kazanılana dek.'}, {'id': 363, 'text': 'The ghost uttered a faint cry of gratitude and joy, falling upon his knees before her.', 'translation': 'Hayalet kızın önünde dizlerinin üzerine çökerek hafif bir minnet ve sevinç çığlığı kopardı.', 'notes': 'cry of gratitude: minnet çığlığı.'}, {'id': 364, 'text': 'He took her small, warm hands in his cold, skeletal fingers and kissed them with reverent tears.', 'translation': 'Kızın küçücük, sıcacık ellerini soğuk, iskeletimsi parmaklarının arasına aldı ve hürmetkar gözyaşlarıyla öptü.', 'notes': 'reverent tears: hürmetkar gözyaşları.'}, {'id': 365, 'text': 'His touch was like ice, and his breath burned like fire, yet Virginia did not draw back.', 'translation': 'Dokunuşu buz gibiydi ve nefesi ateş gibi yakıyordu, yine de Virginia geri çekilmedi.', 'notes': 'did not draw back: geri çekilmedi.'}, {'id': 366, 'text': 'He rose and led her toward the dark, heavily embroidered tapestry that hung at the end of the room.', 'translation': 'Ayağa kalktı ve onu odanın ucunda asılı duran koyu renkli, ağır işlemeli duvar halısına doğru yönlendirdi.', 'notes': 'embroidered tapestry: işlemeli duvar halısı.'}, {'id': 367, 'text': 'As they walked together across the faded carpet, strange and wondrous things began to happen.', 'translation': 'Solgun halının üzerinde birlikte yürürlerken tuhaf ve harikulade şeyler olmaya başladı.', 'notes': 'wondrous things: harikulade şeyler.'}, {'id': 368, 'text': 'The faded huntsmen woven into the tapestry suddenly seemed to move their stitched limbs.', 'translation': 'Duvara asılı halıya dokunmuş soluk avcılar ansızın iplik uzuvlarını kımıldatır gibi oldu.', 'notes': 'stitched limbs: dikişli uzuvlar.'}, {'id': 369, 'text': 'They blew softly through their antique horns, whispering: "Go back, little Virginia! Go back while there is time!"', 'translation': 'Antika borularını usulca öttürerek fısıldadılar: "Geri dön küçük Virginia! Vakit varken geri dön!"', 'notes': 'while there is time: vakit varken.'}, {'id': 370, 'text': 'Fabulous beasts carved upon the Tudor chimney-breast peered down with glowing ruby eyes.', 'translation': 'Tudor şömine kemerine oyulmuş efsanevi canavarlar parıldayan yakut gözleriyle aşağıya baktılar.', 'notes': 'fabulous beasts: efsanevi canavarlar.'}, {'id': 371, 'text': '"Beware, little Virginia!" they hissed in stony accents; "Beware, for we may never see you again!"', 'translation': '"Sakın ha küçük Virginia!" diye taştan bir şiveyle tısladılar; "Sakın, zira seni bir daha hiç göremeyebiliriz!"', 'notes': 'stony accents: taştan şive/ton.'}, {'id': 372, 'text': "The ghost glided on more swiftly, his hand tightening around Virginia's fingers with desperate urgency.", 'translation': "Hayalet eli Virginia'nın parmakları etrafında çaresiz bir ivedilikle sıkılaşarak daha hızlı bir şekilde süzüldü.", 'notes': 'desperate urgency: çaresiz ivedilik/telaş.'}, {'id': 373, 'text': 'Virginia did not falter; her faith and love shielded her against the spectral terrors of the chamber.', 'translation': 'Virginia tereddüt etmedi; inancı ve sevgisi odanın hayaletsi dehşetlerine karşı onu bir kalkan gibi korudu.', 'notes': 'did not falter: tereddüt etmedi, sendelemedi.'}, {'id': 374, 'text': 'They reached the dark corner where the faded figures of Lady Eleanore and Sir Simon were embroidered in silk.', 'translation': "Leydi Eleanore ve Sir Simon'ın solmuş siluetlerinin ipekle işlendiği o karanlık köşeye ulaştılar.", 'notes': 'embroidered in silk: ipekle işlenmiş.'}, {'id': 375, 'text': 'The phantom raised his left arm and made a mystical sign in the air, murmuring forgotten words of power.', 'translation': 'Hortlak sol kolunu kaldırdı ve unutulmuş kudretli kelimeler mırıldanarak havada mistik bir işaret yaptı.', 'notes': 'mystical sign: mistik işaret.'}, {'id': 376, 'text': 'A sudden gust of icy air extinguished the candle in the brass sconce upon the wall.', 'translation': 'Ani bir buz gibi hava esintisi duvardaki pirinç aplikte duran mumu üfleyip söndürdü.', 'notes': 'brass sconce: pirinç duvar apliği/şamdana.'}, {'id': 377, 'text': "The darkness deepened around them until only the faint phosphorescence of the ghost's garments illuminated their path.", 'translation': 'Yalnızca hayaletin elbiselerinin hafif fosforlu ışıltısı yollarını aydınlatana dek karanlık etraflarında daha da derinleşti.', 'notes': 'faint phosphorescence: hafif fosforlu ışıltı.'}, {'id': 378, 'text': '"Do not be afraid, sweet maiden," whispered Sir Simon; "the threshold of eternity is before us."', 'translation': '"Korkmayın tatlı genç kız," diye fısıldadı Sir Simon; "sonsuzluğun eşiği önümüzde duruyor."', 'notes': 'threshold of eternity: sonsuzluğun eşiği.'}, {'id': 379, 'text': '"I trust you, Sir Simon," Virginia answered softly, holding his icy hand with unwavering firmness.', 'translation': '"Size güveniyorum Sir Simon," diye usulca yanıtladı Virginia, sarsılmaz bir kararlılıkla onun buz gibi elini tutarak.', 'notes': 'unwavering firmness: sarsılmaz kararlılık.'}, {'id': 380, 'text': 'The solid oak paneling behind the tapestry began to dissolve and melt like morning mist before their eyes.', 'translation': 'Halı kaplamanın ardındaki som meşe lambri gözlerinin önünde sabah sisi gibi çözülüp erimeye başladı.', 'notes': 'began to dissolve: çözülüp erimeye başladı.'}]}, {'page_no': 20, 'title': 'The Opening of the Wall and the Descent into Darkness', 'tr_title': 'Duvarın Açılması ve Karanlığa İniş', 'vocab_focus': [('wainscot', 'ahşap lambri'), ('cavern', 'mağara, derin kovuk'), ('portal', 'geçit, büyük kapı'), ('abyss', 'uçurum, girdap'), ('engulf', 'yutmak, içine çekmek'), ('vanish', 'kaybolmak, sırra kadem basmak'), ('mysterious', 'esrarengiz'), ('dimension', 'boyut')], 'sentences': [{'id': 381, 'text': 'The ancient wainscoting parted smoothly as if drawn aside by invisible, ghostly hands.', 'translation': 'Asırlık ahşap lambri sanki görünmez, hayaletsi eller tarafından yana çekilmişçesine pürüzsüzce ayrıldı.', 'notes': 'parted smoothly: pürüzsüzce ayrıldı.'}, {'id': 382, 'text': 'Before them opened a great black cavern leading down into the subterranean foundations of the manor.', 'translation': 'Önlerinde malikanenin yer altı temellerine doğru aşağı inen koca, kapkara bir mağara açıldı.', 'notes': 'subterranean foundations: yer altı temelleri.'}, {'id': 383, 'text': 'A bitter, howling wind rushed up from the abyss, smelling of ancient dust, damp stone, and forgotten centuries.', 'translation': 'Uçurumdan yukarı asırlık toz, nemli taş ve unutulmuş yüzyıllar kokan dondurucu, uğultulu bir rüzgar fırladı.', 'notes': 'howling wind: uğultulu rüzgar.'}, {'id': 384, 'text': 'Far below in the gloom, strange voices seemed to murmur mournful prayers in an unknown, ancient tongue.', 'translation': 'Karanlığın çok derinlerinde tuhaf sesler bilinmeyen, antik bir dilde yaslı dualar mırıldanır gibiydi.', 'notes': 'mournful prayers: yaslı dualar.'}, {'id': 385, 'text': "Virginia caught her breath in momentary dread, but she tightened her small grip upon the ghost's hand.", 'translation': 'Virginia bir anlık dehşetle soluğunu tuttu fakat hayaletin elindeki o küçücük tutuşunu daha da sıkılaştırdı.', 'notes': 'caught her breath: soluğunu tuttu.'}, {'id': 386, 'text': '"Step forward with me into the shadow of the grave," said Sir Simon in a voice of profound, trembling awe.', 'translation': '"Mezarın gölgesine benimle birlikte adım atın," dedi Sir Simon derin, titrek bir huşu içindeki bir sesle.', 'notes': 'trembling awe: titrek huşu.'}, {'id': 387, 'text': '"Have no fear of the dark, for the pure light of your innocent soul shall be our lantern."', 'translation': '"Karanlıktan hiç korkmayın zira masum ruhunuzun tertemiz ışığı bizim fenerimiz olacaktır."', 'notes': 'pure light: tertemiz ışık.'}, {'id': 388, 'text': 'Virginia stepped resolutely across the threshold, her white riding skirts brushing against the rough, cold stone.', 'translation': 'Virginia beyaz binici eteği pürüzlü, soğuk taşa sürterek kararlı bir şekilde eşikten içeri adım attı.', 'notes': 'stepped resolutely: kararlılıkla adım attı.'}, {'id': 389, 'text': 'The moment both had crossed the boundary, the oak paneling snapped violently shut behind them with a loud crash.', 'translation': 'İkisi de sınırı aştığı anda meşe kaplama arkalarından yüksek bir gürültüyle şiddetle kapandı.', 'notes': 'snapped violently shut: şiddetle kapandı.'}, {'id': 390, 'text': 'The heavy tapestry fell back into place, concealing the hidden entrance completely from mortal eyes.', 'translation': 'Ağır duvar halısı fani gözlerden gizli girişi tamamen örterek yerine geri düştü.', 'notes': 'concealing from eyes: gözlerden saklayan.'}, {'id': 391, 'text': 'The Tapestry Room became once again entirely quiet, empty, and bathed in the peaceful afternoon sunlight.', 'translation': 'Halı Odası bir kez daha tamamen sessiz, bomboş ve öğleden sonrasının huzurlu gün ışığıyla yıkanmış bir hale büründü.', 'notes': 'bathed in sunlight: gün ışığında yıkanmış.'}, {'id': 392, 'text': 'Outside, the birds chirped merrily in the ivy, and the gentle wind rustled through the great beech trees.', 'translation': 'Dışarıda sarmaşıkların arasında kuşlar neşeyle cıvıldıyor, tatlı rüzgar ulu kayın ağaçlarının arasında hışırdıyordu.', 'notes': 'birds chirped merrily: kuşlar neşeyle cıvıldadı.'}, {'id': 393, 'text': 'No one in the bustling house suspected that the beloved daughter of the American Minister had vanished into eternity.', 'translation': "Hareketli evde hiç kimse Amerikalı Elçi'nin çok sevilen kızının sonsuzluğa karışıp kaybolduğundan şüphelenmedi.", 'notes': 'vanished into eternity: sonsuzluğa karışıp kayboldu.'}, {'id': 394, 'text': 'Down in the subterranean darkness, Virginia felt herself descending an endless spiral staircase cut into the living rock.', 'translation': 'Aşağıda, yer altının karanlığında Virginia som kayaya oyulmuş sonsuz bir helezon merdivenden indiğini hissetti.', 'notes': 'spiral staircase: döner/helezon merdiven.'}, {'id': 395, 'text': 'Ghostly shapes floated past in the cold shadows, whispering solemn words that she could not comprehend.', 'translation': 'Soğuk gölgelerin içinden anlayamadığı vakur sözler fısıldayarak hayaletsi siluetler süzülüp geçti.', 'notes': 'ghostly shapes floated: hayaletsi siluetler süzüldü.'}, {'id': 396, 'text': 'Huge winged phantoms hovered above her head, but they bowed their dark pinions reverently before her purity.', 'translation': 'Başının üzerinde kocaman kanatlı hayaletler uçuştu fakat onun masumiyeti karşısında karanlık kanatlarını hürmetle eğdiler.', 'notes': 'winged phantoms: kanatlı hayaletler.'}, {'id': 397, 'text': 'The ghost held her hand tenderly, guiding her steps through the perilous gloom of the forgotten vaults.', 'translation': 'Hayalet unutulmuş mahzenlerin tehlikeli karanlığında adımlarına rehberlik ederek elini şefkatle tuttu.', 'notes': 'perilous gloom: tehlikeli karanlık.'}, {'id': 398, 'text': '"We are near the garden," Sir Simon whispered in a voice filled with profound peace; "listen to the nightingale!"', 'translation': '"Bahçeye yaklaştık," diye fısıldadı Sir Simon derin bir huzurla dolu bir sesle; "bülbülü dinle!"', 'notes': 'profound peace: derin huzur.'}, {'id': 399, 'text': 'Faint, heavenly music seemed to echo from afar, sweeter than any melody mortal ears had ever heard.', 'translation': 'Fani kulakların bugüne dek duyduğu her melodiden daha tatlı, uzaktan yankılanan hafif, semavi bir müzik duyuldu.', 'notes': 'heavenly music: semavi müzik.'}, {'id': 400, 'text': 'Virginia knelt down upon the cold stone floor and began to weep and pray for the soul of Sir Simon de Canterville.', 'translation': "Virginia soğuk taş zemine diz çöktü ve Sir Simon de Canterville'in ruhu için ağlayıp dua etmeye başladı.", 'notes': 'knelt down upon floor: yere diz çöktü.'}]}, {'page_no': 21, 'title': 'The Disappearance of Virginia and the General Alarm', 'tr_title': "Virginia'nın Kayboluşu ve Genel Alarm", 'vocab_focus': [('frantic', 'çılgına dönmüş, telaşlı'), ('search', 'arama, araştırma'), ('constable', 'polis memuru, zaptiye'), ('river', 'nehir'), ('ponds', 'göletler, havuzlar'), ('gypsy', 'çingene'), ('woodland', 'koruluk, ormanlık alan'), ('despair', 'umutsuzluk, keder')], 'sentences': [{'id': 401, 'text': "At four o'clock, the usual tea was laid out in the library, but Miss Virginia did not make her appearance.", 'translation': 'Saat dörtte mutat çay kütüphaneye kuruldu fakat Bayan Virginia ortalıkta görünmedi.', 'notes': 'usual tea was laid: mutat çay hazırlandı.'}, {'id': 402, 'text': 'Mrs. Otis was not at all anxious at first, supposing that the girl had gone into the garden to gather flowers.', 'translation': 'Kızın çiçek toplamak için bahçeye gittiğini varsayan Bayan Otis ilk başta hiç endişelenmedi.', 'notes': 'not anxious at first: ilk başta endişelenmedi.'}, {'id': 403, 'text': "However, when six o'clock struck and Virginia had still not returned, the family became seriously alarmed.", 'translation': 'Fakat saat altıyı vurduğunda ve Virginia hâlâ dönmediğinde aile ciddi biçimde telaşlandı.', 'notes': 'seriously alarmed: ciddi biçimde telaşlandı.'}, {'id': 404, 'text': 'Washington and the twins searched every bedroom, gallery, attic, and outhouse on the estate.', 'translation': 'Washington ve ikizler malikanedeki her yatak odasını, galeriyi, tavan arasını ve müştemilatı aradılar.', 'notes': 'searched every room: her odayı aradılar.'}, {'id': 405, 'text': 'The servants were dispatched with lanterns to search the gardens, orchards, stables, and park avenues.', 'translation': 'Hizmetkarlar bahçeleri, meyve bahçelerini, ahırları ve park yollarını aramak üzere fenerlerle sevk edildi.', 'notes': 'dispatched with lanterns: fenerlerle sevk edildi.'}, {'id': 406, 'text': 'Not a single trace of the missing girl could be discovered anywhere on the premises.', 'translation': 'Mülkün hiçbir yerinde kayıp kızın tek bir izine dahi rastlanamadı.', 'notes': 'not a single trace: tek bir iz bile yok.'}, {'id': 407, 'text': 'Young Lord Cheshire, who had remained to dine with them, was half frantic with agony and fear.', 'translation': 'Onlarla akşam yemeği yemek için kalan genç Lord Cheshire ıstırap ve korkudan adeta çılgına dönmüştü.', 'notes': 'frantic with agony: ıstıraptan çılgına dönmüş.'}, {'id': 408, 'text': '"She was wearing her riding habit; she must have gone back to the stables!" the young Duke cried wildly.', 'translation': '"Binici giysisini giyiyordu; ahırlara geri gitmiş olmalı!" diye delice haykırdı genç Dük.', 'notes': 'cried wildly: delice haykırdı.'}, {'id': 409, 'text': 'They examined the stables immediately, but her pony was standing quietly in its stall with its bridle off.', 'translation': 'Derhal ahırları incelediler fakat midillisi gemi çıkarılmış vaziyette bölmesinde sakince duruyordu.', 'notes': 'standing in stall: bölmesinde duran.'}, {'id': 410, 'text': 'Mr. Otis immediately dispatched telegrams to Scotland Yard and summoned the local police constable of Ascot.', 'translation': "Bay Otis derhal Scotland Yard'a telgraflar çekti ve Ascot'un yerel polis memurunu çağırdı.", 'notes': 'dispatched telegrams: telgraflar çekti.'}, {'id': 411, 'text': 'The carp ponds were dragged with iron hooks, and the old well in the courtyard was examined with torches.', 'translation': 'Sazan havuzları demir kancalarla tarandı ve avludaki eski kuyu meşalelerle incelendi.', 'notes': 'dragged with hooks: kancalarla tarandı.'}, {'id': 412, 'text': 'A band of traveling gypsies had camped that morning in Blackfell Hollow, three miles away.', 'translation': "Gezgin bir çingene grubu o sabah üç mil uzaktaki Blackfell Çukuru'nda kamp kurmuştu.", 'notes': 'traveling gypsies: gezgin çingeneler.'}, {'id': 413, 'text': 'Mr. Otis, Washington, and the young Duke rode out on horseback at full gallop to inspect their camp.', 'translation': 'Bay Otis, Washington ve genç Dük kamplarını aramak için at sırtında dörtnala yola çıktılar.', 'notes': 'rode at full gallop: dörtnala at sürdüler.'}, {'id': 414, 'text': 'The gypsies had departed hastily, but when overtaken by the riders, they proved completely innocent of any abduction.', 'translation': 'Çingeneler apar topar ayrılmışlardı fakat atlılar yetiştiğinde herhangi bir kaçırma olayında tamamen masum oldukları anlaşıldı.', 'notes': 'innocent of abduction: kaçırma suçundan masum.'}, {'id': 415, 'text': 'Four of their men even returned with Mr. Otis to assist in scouring the dense woods through the night.', 'translation': 'Hatta adamlardan dördü gece boyunca sık ormanları taramaya yardım etmek için Bay Otis ile birlikte geri döndü.', 'notes': 'assist in scouring: taramaya yardım etmek.'}, {'id': 416, 'text': "By eleven o'clock at night, the entire countryside was aroused, with lanterns moving across every field and lane.", 'translation': 'Gece saat on bir olduğunda her tarla ve patika boyunca hareket eden fenerlerle tüm civar ayağa kaldırılmıştı.', 'notes': 'entire countryside aroused: tüm civar ayağa kalktı.'}, {'id': 417, 'text': 'Mrs. Otis was in a state of complete nervous collapse, comforted tenderly by the weeping housekeeper.', 'translation': 'Bayan Otis, ağlayan kahya tarafından şefkatle teskin edilerek tam bir sinir çöküntüsü içindeydi.', 'notes': 'state of collapse: çöküntü hali.'}, {'id': 418, 'text': "Even the irrepressible twins were subdued and silent, holding their mother's trembling hands in the library.", 'translation': 'Ele avuca sığmaz ikizler bile kütüphanede annelerinin titreyen ellerini tutarak sessiz ve pusmuş vaziyetteydiler.', 'notes': 'subdued and silent: pusmuş ve sessiz.'}, {'id': 419, 'text': 'Mr. Otis returned to the Chase at midnight, exhausted, drenched with rain, and utterly broken in spirit.', 'translation': 'Bay Otis gece yarısı köşke bitkin, yağmurdan sırılsıklam ve ruhen tamamen çökmüş bir halde döndü.', 'notes': 'broken in spirit: ruhen çökmüş.'}, {'id': 420, 'text': 'It seemed impossible that a living girl could vanish so completely from the center of an English country manor.', 'translation': 'Yaşayan bir genç kızın bir İngiliz kır malikanesinin ortasından böylesine tamamen yok olması imkansız görünüyordu.', 'notes': 'vanish so completely: böylesine tamamen yok olmak.'}]}, {'page_no': 22, 'title': "The Midnight Thunder and Virginia's Return", 'tr_title': "Gece Yarısı Gök Gürültüsü ve Virginia'nın Dönüşü", 'vocab_focus': [('stroke', 'vuruş, çalış'), ('midnight', 'gece yarısı'), ('chimes', 'çan sesleri'), ('panel', 'ahşap panel, bölme'), ('casket', 'mücevher kutusu, sanduka'), ('jewel', 'mücevher'), ('return', 'geri dönüş'), ('miraculous', 'mucizevi')], 'sentences': [{'id': 421, 'text': 'Just as the great hall clock began to strike the solemn midnight chimes, a sudden, blinding flash lit up the house.', 'translation': 'Tam büyük salon saati ağırbaşlı gece yarısı vuruşlarını çalmaya başladığı anda ani ve kör edici bir şimşek evi aydınlattı.', 'notes': 'solemn midnight chimes: ağırbaşlı gece yarısı çanları.'}, {'id': 422, 'text': 'A tremendous peel of thunder shook the entire structure, rattling every leaded window in the galleries.', 'translation': 'Muazzam bir gök gürültüsü galerilerdeki her kurşunlu camı zangırdatarak bütün yapıyı sarstı.', 'notes': 'tremendous peel of thunder: muazzam gök gürültüsü patlaması.'}, {'id': 423, 'text': 'Immediately following the thunder, a strain of unearthly, celestial music floated down the corridors.', 'translation': 'Gök gürültüsünün hemen ardından koridorlardan aşağı dünyevi olmayan, semavi bir müzik ezgisi süzüldü.', 'notes': 'unearthly celestial music: semavi dünya dışı müzik.'}, {'id': 424, 'text': 'The family leaped to their feet in astonishment as the melody swelled with sweet, angelic harmonies.', 'translation': 'Melodi tatlı, meleksi ahenklerle coşarken aile büyük bir şaşkınlıkla ayağa fırladı.', 'notes': 'angelic harmonies: meleksi ahenkler.'}, {'id': 425, 'text': 'Suddenly, with a loud, hollow crash, the carved oak panel at the head of the staircase flew wide open!', 'translation': 'Ansızın, yüksek ve boğuk bir gümbürtüyle merdiven başındaki oymalı meşe panel ardına kadar açıldı!', 'notes': 'flew wide open: ardına kadar açıldı.'}, {'id': 426, 'text': 'Out stepped Virginia, pale and solemn, looking like an angelic vision in the glowing moonlight.', 'translation': 'Dışarı parıldayan ay ışığında meleksi bir hayali andıran, solgun ve vakur haliyle Virginia çıktı.', 'notes': 'angelic vision: meleksi hayal/görüntü.'}, {'id': 427, 'text': 'In her slender hands, she carried a heavy antique casket of beaten silver, embossed with curious devices.', 'translation': 'Narin ellerinde tuhaf motiflerle kabartılmış, dövme gümüşten yapılmış ağır antika bir mücevher sandukası taşıyordu.', 'notes': 'casket of beaten silver: dövme gümüş sanduka.'}, {'id': 428, 'text': '"Papa! Mamma!" she cried softly, running down the steps into the outstretched arms of her weeping mother.', 'translation': '"Babacığım! Anneciğim!" diye usulca haykırdı, ağlayan annesinin açık kollarına doğru basamaklardan aşağı koşarak.', 'notes': 'outstretched arms: açılmış/uzanmış kollar.'}, {'id': 429, 'text': 'Mrs. Otis smothered her with passionate kisses, while Mr. Otis clasped her tightly to his breast.', 'translation': 'Bayan Otis onu tutkulu öpücüklere boğarken Bay Otis kızını göğsüne sıkıca bastırdı.', 'notes': 'clasped tightly: sıkıca bastırdı.'}, {'id': 430, 'text': 'The young Duke of Cheshire threw his arms around her neck and wept tears of unutterable joy.', 'translation': 'Genç Cheshire Dükü kollarını boynuna doladı ve tarif edilemez bir sevinç gözyaşları döktü.', 'notes': 'unutterable joy: tarif edilemez sevinç.'}, {'id': 431, 'text': 'The twins performed a triumphant war-dance around the group, whooping with noisy boyish delight.', 'translation': 'İkizler gürültülü çocukça bir neşeyle naralar atarak grubun etrafında muzaffer bir savaş dansı yaptılar.', 'notes': 'triumphant war-dance: muzaffer savaş dansı.'}, {'id': 432, 'text': '"My darling child, where have you been?" cried Mrs. Otis as soon as she could find her voice.', 'translation': '"Canım yavrum, neredeydin sen?" diye haykırdı Bayan Otis sesini bulabildiği ilk anda.', 'notes': 'could find her voice: sesini bulabildi.'}, {'id': 433, 'text': '"We have looked for you all over the county, and your father nearly went out of his mind with grief!"', 'translation': '"Seni bütün vilayette aradık ve baban kederden neredeyse aklını kaçıracaktı!"', 'notes': 'out of his mind: aklını kaçırmış.'}, {'id': 434, 'text': '"I have been with the ghost," Virginia answered quietly, her eyes shining with mystical radiance.', 'translation': '"Hayaletin yanındaydım," diye usulca yanıtladı Virginia, gözleri mistik bir ışıltıyla parlayarak.', 'notes': 'mystical radiance: mistik ışıltı.'}, {'id': 435, 'text': '"He is dead, and you need never be annoyed by him again in this house."', 'translation': '"O öldü ve bu evde onun tarafından bir daha asla rahatsız edilmeyeceksiniz."', 'notes': 'he is dead: o öldü.'}, {'id': 436, 'text': '"He had been very wicked, but he was truly sorry for all that he had done."', 'translation': '"Çok kötü biriymiş fakat yaptığı her şey için gerçekten çok pişmandı."', 'notes': 'truly sorry: gerçekten pişman.'}, {'id': 437, 'text': '"And he gave me this beautiful box of precious jewels before he fell into his eternal rest."', 'translation': '"Ve o ebedi istirahatine çekilmeden önce bana bu değerli mücevherlerle dolu güzel sandukayı verdi."', 'notes': 'box of precious jewels: değerli mücevher kutusu.'}, {'id': 438, 'text': 'She opened the silver casket: inside lay glittering rubies, fiery emeralds, and necklaces of magnificent pearls.', 'translation': 'Gümüş sandukayı açtı: İçinde ışıl ışıl parlayan yakutlar, alev gibi zümrütler ve muhteşem incilerden kolyeler yatıyordu.', 'notes': 'glittering rubies: parıldayan yakutlar.'}, {'id': 439, 'text': 'The entire family stared at the jewels in astonishment, completely speechless before the miraculous revelation.', 'translation': 'Tüm aile bu mucizevi ifşa karşısında tamamen dilsiz kalarak hayret içinde mücevherlere bakakaldı.', 'notes': 'miraculous revelation: mucizevi ifşa/keşif.'}, {'id': 440, 'text': '"Come with me," said Virginia gravely, "and I will show you where his mortal body has lain for centuries."', 'translation': '"Benimle gelin," dedi Virginia ciddiyetle, "ve size onun fani bedeninin yüzyıllardır nerede yattığını göstereyim."', 'notes': 'mortal body: fani beden.'}]}, {'page_no': 23, 'title': 'The Blossoming of the Barren Almond Tree', 'tr_title': 'Kurumuş Badem Ağacının Çiçek Açması', 'vocab_focus': [('almond tree', 'badem ağacı'), ('blossom', 'çiçek açmak, çiçek'), ('forgiven', 'bağışlanmış, affedilmiş'), ('fragrance', 'hoş koku, rayiha'), ('redemption', 'kurtuluş, arınma'), ('tears', 'gözyaşları'), ('peace', 'huzur, barış'), ('skeleton', 'iskelet')], 'sentences': [{'id': 441, 'text': 'Carrying candles and lanterns, the entire household followed the young girl up the oak staircase.', 'translation': 'Mumlar ve fenerler taşıyarak bütün hane halkı meşe merdivenlerden genç kızı takip etti.', 'notes': 'carrying lanterns: fenerler taşıyan.'}, {'id': 442, 'text': 'She led them through the secret opening in the wainscot and down a narrow, damp corridor cut through stone.', 'translation': 'Onları ahşap lambrideki gizli geçitten ve taşa oyulmuş dar, nemli bir koridordan aşağıya götürdü.', 'notes': 'secret opening: gizli geçit/açıklık.'}, {'id': 443, 'text': 'At last they came to a heavy oak door studded with iron nails and equipped with a massive rusted bolt.', 'translation': 'Nihayet demir çivilerle perçinlenmiş ve kocaman paslı bir sürgüyle donatılmış ağır bir meşe kapıya geldiler.', 'notes': 'rusted bolt: paslı sürgü.'}, {'id': 444, 'text': 'Virginia pushed the creaking door open, and they found themselves in a low, vaulted dungeon room.', 'translation': 'Virginia gıcırdayan kapıyı itip açtı ve kendilerini basık tavanlı, tonozlu bir zindan odasında buldular.', 'notes': 'vaulted dungeon: tonozlu zindan.'}, {'id': 445, 'text': 'High in the stone wall was a small iron-grated window, through which the silvery moon poured a cold beam.', 'translation': 'Taş duvarın yukarısında, gümüşsü ayın soğuk bir ışık huzmesi akıttığı küçük, demir parmaklıklı bir pencere vardı.', 'notes': 'iron-grated window: demir parmaklıklı pencere.'}, {'id': 446, 'text': 'Chained securely to an enormous iron ring in the wall was a human skeleton, lying outstretched upon the stone floor.', 'translation': 'Duvardaki devasa bir demir halkaya sıkıca zincirlenmiş bir insan iskeleti taş zeminde boylu boyunca uzanmış yatıyordu.', 'notes': 'human skeleton: insan iskeleti.'}, {'id': 447, 'text': 'Beside the skeletal arms lay an ancient earthenware jug and a deep plate, placed just beyond reach.', 'translation': 'İskeletimsi kolların yanında, tam uzanamayacağı mesafeye yerleştirilmiş antik bir toprak testi ve derin bir tabak duruyordu.', 'notes': 'earthenware jug: topraktan testi.'}, {'id': 448, 'text': 'The jug and plate were completely empty, bearing silent witness to the cruel starvation of Sir Simon de Canterville.', 'translation': "Testi ve tabak tamamen boştu; Sir Simon de Canterville'in maruz kaldığı zalimce açlığa sessiz bir şahitlik ediyordu.", 'notes': 'silent witness: sessiz şahit.'}, {'id': 449, 'text': 'Virginia knelt beside the skeleton, folded her delicate hands, and bowed her head in silent prayer.', 'translation': 'Virginia iskeletin yanına diz çöktü, narin ellerini birleştirdi ve sessiz bir duayla başını eğdi.', 'notes': 'bowed her head: başını öne eğdi.'}, {'id': 450, 'text': 'The rest of the family stood in reverent awe, touched by the solemn mystery of the ancient tragedy.', 'translation': 'Ailenin geri kalanı, asırlık trajedinin vakur gizeminden duygulanarak hürmet dolu bir huşu içinde ayakta durdu.', 'notes': 'reverent awe: hürmet dolu huşu.'}, {'id': 451, 'text': '"God has forgiven him," Virginia whispered, rising softly; "his long centuries of torment are over."', 'translation': '"Tanrı onu bağışladı," diye fısıldadı Virginia, usulca ayağa kalkarak; "onun asırlar süren azabı sona erdi artık."', 'notes': 'centuries of torment: asırlar süren azap.'}, {'id': 452, 'text': 'Just then, one of the twins exclaimed in sudden wonder: "Look through the grate into the churchyard!"', 'translation': 'Tam o sırada ikizlerden biri ani bir hayretle haykırdı: "Parmaklığın arasından kilise mezarlığına bakın!"', 'notes': 'exclaimed in wonder: hayretle haykırdı.'}, {'id': 453, 'text': 'Everyone looked through the narrow slit of the dungeon window out into the moonlit park.', 'translation': 'Herkes zindan penceresinin dar yarığından dışarı, ay ışığıyla aydınlanan parka baktı.', 'notes': 'narrow slit: dar yarık/aralık.'}, {'id': 454, 'text': 'Standing beside the ancient chapel was the old almond tree, which had been withered, bare, and dead for fifty years.', 'translation': 'Eski şapelin yanında duran ve elli yıldır solgun, çıplak ve kupkuru olan o yaşlı badem ağacıydı bu.', 'notes': 'old almond tree: yaşlı badem ağacı.'}, {'id': 455, 'text': 'Before their astonished eyes, every single branch had suddenly burst into magnificent, fragrant white blossoms!', 'translation': 'Hayrete düşen gözlerinin önünde her bir dal ansızın muhteşem, mis kokulu bembeyaz çiçeklerle donanmıştı!', 'notes': 'burst into blossoms: çiçeklerle donandı/açtı.'}, {'id': 456, 'text': 'The silver blossoms shone brilliantly under the moon, filling the night breeze with an exquisite perfume.', 'translation': 'Gümüş çiçekler ayın altında ışıl ışıl parlıyor, gece esintisini nefis bir rayihayla dolduruyordu.', 'notes': 'exquisite perfume: nefis rayiha/koku.'}, {'id': 457, 'text': '"The prophecy is fulfilled!" cried Washington with emotion; "the barren almond tree has borne its fruit!"', 'translation': '"Kehanet gerçekleşti!" diye duygulanarak bağırdı Washington; "kurumuş badem ağacı meyvesini/çiçeğini verdi!"', 'notes': 'prophecy is fulfilled: kehanet gerçekleşti.'}, {'id': 458, 'text': 'Mrs. Otis wiped a tear from her cheek, feeling a deep spiritual peace settle over Canterville Chase.', 'translation': "Canterville Köşkü'nün üzerine derin bir manevi huzurun çöktüğünü hissederek Bayan Otis yanağından bir damla yaşı sildi.", 'notes': 'spiritual peace: manevi huzur.'}, {'id': 459, 'text': 'The ancient curse was broken forever; the ghost was forgiven, and his soul was granted eternal rest.', 'translation': 'Asırlık lanet sonsuza dek bozuldu; hayalet bağışlandı ve ruhuna ebedi huzur bahşedildi.', 'notes': 'ancient curse was broken: asırlık lanet bozuldu.'}, {'id': 460, 'text': 'They quietly closed the iron door, leaving the sacred skeleton in the keeping of the holy moonlight.', 'translation': 'Kutsal iskeleti mübarek ay ışığının muhafazasına bırakarak demir kapıyı sessizce kapattılar.', 'notes': 'keeping of moonlight: ay ışığının muhafazası.'}]}, {'page_no': 24, 'title': 'The Solemn Funeral of Sir Simon de Canterville', 'tr_title': "Sir Simon de Canterville'in Görkemli Cenazesi", 'vocab_focus': [('funeral', 'cenaze töreni'), ('cortege', 'cenaze alayı'), ('hearse', 'cenaze arabası'), ('plume', 'sorguç, tüy demeti'), ('rector', 'papaz'), ('torch', 'meşale'), ('cemetery', 'mezarlık'), ('burial', 'defin, gömme')], 'sentences': [{'id': 461, 'text': "Four nights later, at eleven o'clock, a solemn and impressive funeral cortege moved from Canterville Chase.", 'translation': "Dört gece sonra saat on birde, Canterville Köşkü'nden ağırbaşlı ve etkileyici bir cenaze alayı yola çıktı.", 'notes': 'funeral cortege: cenaze alayı.'}, {'id': 462, 'text': 'The hearse was drawn by eight magnificent black horses, each wearing a nodding plume of ostrich feathers.', 'translation': 'Cenaze arabası, her biri sallanan devekuşu tüylerinden bir sorguç takmış sekiz muhteşem siyah at tarafından çekiliyordu.', 'notes': 'nodding plume: sallanan tüy sorgucu.'}, {'id': 463, 'text': 'The ancient leaden coffin was covered with a rich purple pall embroidered with the golden arms of the Cantervilles.', 'translation': 'Eski kurşun tabut, Canterville ailesinin altın armalarıyla işlenmiş zengin mor bir örtüyle örtülmüştü.', 'notes': 'purple pall: mor tabut örtüsü.'}, {'id': 464, 'text': 'By the side of the hearse walked the servants and estate tenants carrying lighted wax torches.', 'translation': 'Cenaze arabasının yanında yanan balmumu meşaleleri taşıyan hizmetkarlar ve malikane kiracıları yürüyordu.', 'notes': 'lighted wax torches: yanan balmumu meşaleleri.'}, {'id': 465, 'text': 'Lord Canterville himself had traveled specially from Wales to attend as the chief mourner for his ancestor.', 'translation': "Lord Canterville'in bizzat kendisi atası için baş yas tutan kişi olarak katılmak üzere Galler'den hususi olarak gelmişti.", 'notes': 'chief mourner: baş yas tutan.'}, {'id': 466, 'text': 'He sat in the first carriage alongside little Virginia, holding her hand with genuine gratitude.', 'translation': "İlk arabada küçük Virginia'nın yanında oturdu ve sahici bir minnetle onun elini tuttu.", 'notes': 'genuine gratitude: sahici minnet.'}, {'id': 467, 'text': 'Next came the United States Minister and his wife, followed by Washington and the two boys.', 'translation': 'Hemen ardından Birleşik Devletler Elçisi ve eşi, onların arkasından ise Washington ve iki erkek çocuk geliyordu.', 'notes': 'United States Minister: Birleşik Devletler Elçisi.'}, {'id': 468, 'text': 'A deep grave had been dug in the corner of the ancient churchyard, beneath the blossoming almond tree.', 'translation': 'Eski kilise mezarlığının köşesinde, çiçek açmış badem ağacının altında derin bir mezar kazılmıştı.', 'notes': 'deep grave: derin mezar.'}, {'id': 469, 'text': 'The venerable rector of the parish read the burial service in a solemn, clear voice.', 'translation': 'Bölgenin muhterem papazı defin duasını vakur, berrak bir ses tonuyla okudu.', 'notes': 'burial service: defin duası/töreni.'}, {'id': 470, 'text': 'When the ceremonies were concluded, Virginia stepped forward and laid a large cross of white and pink almond blossoms upon the coffin.', 'translation': 'Tören bittiğinde Virginia öne çıktı ve tabutun üzerine beyaz ve pembe badem çiçeklerinden yapılmış büyük bir haç bıraktı.', 'notes': 'cross of almond blossoms: badem çiçeklerinden haç.'}, {'id': 471, 'text': 'As she did so, the moon came out from behind a silver cloud and flooded the little churchyard in brilliant light.', 'translation': 'O bunu yaptığı sırada ay gümüş bir bulutun ardından çıktı ve küçük kilise mezarlığını parlak bir ışığa boğdu.', 'notes': 'flooded in brilliant light: parlak ışığa boğdu.'}, {'id': 472, 'text': 'From a distant thicket, a nightingale began to sing with celestial sweetness, welcoming the weary spirit to peace.', 'translation': 'Uzak bir çalılıktan bir bülbül, yorgun ruhu huzura davet ederek semavi bir tatlılıkla şakımaya başladı.', 'notes': 'celestial sweetness: semavi tatlılık.'}, {'id': 473, 'text': "Virginia remembered the ghost's description of the Garden of Death and wiped away a quiet tear of joy.", 'translation': 'Virginia hayaletin Ölüm Bahçesi tarifini hatırladı ve sessiz bir sevinç gözyaşını sildi.', 'notes': 'tear of joy: sevinç gözyaşı.'}, {'id': 474, 'text': 'The heavy oak earth was shoveled gently into the grave, covering the ancestral bones forever.', 'translation': 'Ata yadigarı kemikleri ebediyen örterek ağır meşe toprağı mezara usulca kürendi.', 'notes': 'ancestral bones: ata yadigarı kemikler.'}, {'id': 475, 'text': 'The next morning, Mr. Otis attempted to return the valuable casket of jewels to Lord Canterville.', 'translation': "Ertesi sabah Bay Otis o kıymetli mücevher sandukasını Lord Canterville'e iade etmeye kalkıştı.", 'notes': 'attempted to return: iade etmeye kalkıştı.'}, {'id': 476, 'text': '"These are British heirlooms of immense value, and my family cannot accept such costly treasures," said Mr. Otis.', 'translation': '"Bunlar muazzam değerde İngiliz aile yadigarlarıdır ve ailem böylesine pahalı hazineleri kabul edemez," dedi Bay Otis.', 'notes': 'costly treasures: pahalı hazineler.'}, {'id': 477, 'text': 'Lord Canterville smiled and refused to take back a single ring: "My dear friend, Virginia earned them bravely."', 'translation': 'Lord Canterville gülümsedi ve tek bir yüzüğü dahi geri almayı reddetti: "Sevgili dostum, Virginia onları cesurca hak etti."', 'notes': 'earned them bravely: onları cesurca hak etti.'}, {'id': 478, 'text': '"Sir Simon gave them to her, and if I were to take them, the old gentleman would certainly jump out of his grave!"', 'translation': '"Sir Simon onları ona verdi ve eğer onları alacak olursam o ihtiyar beyefendi kesinlikle mezarından fırlardı!"', 'notes': 'jump out of grave: mezarından fırlamak.'}, {'id': 479, 'text': '"Besides, she brought peace to our ancestral house, and our whole family is eternally in her debt."', 'translation': '"Hem o ata yadigarı evimize huzur getirdi ve bütün ailemiz ona ebediyen minnettardır."', 'notes': 'eternally in debt: ebediyen minnettar/borçlu.'}, {'id': 480, 'text': 'And so, with universal approval, Miss Virginia retained the magnificent collection of antique jewels.', 'translation': 'Ve böylece herkesin onayıyla Bayan Virginia o muhteşem antika mücevher koleksiyonunu elinde tuttu.', 'notes': 'universal approval: herkesin onayı.'}]}, {'page_no': 25, 'title': 'The Duchess of Cheshire and the Memory of Love', 'tr_title': 'Cheshire Düşesi ve Sevginin Hatırası', 'vocab_focus': [('wedding', 'düğün, nikah'), ('duchess', 'düşes'), ('coronet', 'küçük taç, soyluluk tacı'), ('secret', 'sır, gizem'), ('grave', 'mezar, kabir'), ('twilight', 'alacakaranlık'), ('mystery', 'gizem, sır'), ('eternity', 'ebediyet, sonsuzluk')], 'sentences': [{'id': 481, 'text': 'A few years later, when Virginia reached her twentieth spring, a brilliant society wedding took place in London.', 'translation': "Birkaç yıl sonra, Virginia yirminci baharına ulaştığında Londra'da parlak bir sosyete düğünü gerçekleşti.", 'notes': 'brilliant society wedding: parlak sosyete düğünü.'}, {'id': 482, 'text': "She was married to the young Duke of Cheshire at the fashionable church of St. George's, Hanover Square.", 'translation': "Hanover Meydanı'ndaki gözde St. George Kilisesi'nde genç Cheshire Dükü ile evlendi.", 'notes': 'fashionable church: gözde/sosyetik kilise.'}, {'id': 483, 'text': 'The bride looked radiantly beautiful, wearing the antique Canterville diamond coronet upon her golden hair.', 'translation': 'Altın saçlarının üzerine antika Canterville elmas tacını takan gelin göz alıcı güzellikteydi.', 'notes': 'diamond coronet: elmas taç.'}, {'id': 484, 'text': 'Her father was proud, her mother was joyful, and the twins served as energetic pages of honor in velvet doublets.', 'translation': 'Babası gururlu, annesi neşeliydi ve ikizler kadife yelekler içinde enerjik nedimler olarak hizmet ettiler.', 'notes': 'pages of honor: onur nedimleri.'}, {'id': 485, 'text': 'After the honeymoon in Italy, the young Duke and Duchess returned to England to visit Canterville Chase.', 'translation': "İtalya'daki balayının ardından genç Dük ve Düşes Canterville Köşkü'nü ziyaret etmek üzere İngiltere'ye döndüler.", 'notes': "honeymoon in Italy: İtalya'da balayı."}, {'id': 486, 'text': 'On a quiet summer evening at dusk, they walked together down the avenue to the ancient churchyard.', 'translation': 'Alacakaranlıkta sakin bir yaz akşamında ağaçlı yoldan eski kilise mezarlığına doğru birlikte yürüdüler.', 'notes': 'quiet summer evening: sakin yaz akşamı.'}, {'id': 487, 'text': 'The almond tree was in lush green leaf, and sweet white roses climbed over the weathered stone walls.', 'translation': 'Badem ağacı gür yeşil yapraklar içindeydi ve tatlı beyaz güller yıpranmış taş duvarlara tırmanıyordu.', 'notes': 'lush green leaf: gür yeşil yaprak.'}, {'id': 488, 'text': 'They stood beside the quiet grassy mound where the bones of Sir Simon de Canterville rested in sacred peace.', 'translation': "Sir Simon de Canterville'in kemiklerinin kutsal bir huzur içinde yattığı o sakin çimenli tümseğin yanında durdular.", 'notes': 'grassy mound: çimenli tümsek/mezar.'}, {'id': 489, 'text': 'Virginia knelt down and placed a garland of fresh summer roses upon the simple stone marker.', 'translation': 'Virginia diz çöktü ve sade mezar taşının üzerine taze yaz güllerinden yapılmış bir çelenk bıraktı.', 'notes': 'garland of roses: gül çelengi.'}, {'id': 490, 'text': "The young Duke put his arm around his wife's waist, looking at her with deep affection and tenderness.", 'translation': 'Genç Dük kolunu karısının beline doladı, ona derin bir sevgi ve şefkatle baktı.', 'notes': 'deep affection: derin sevgi.'}, {'id': 491, 'text': '"Virginia, a wife should have no secrets from her husband," he whispered gently into her ear.', 'translation': '"Virginia, bir kadının kocasından hiçbir sırrı olmamalı," diye kulağına nazikçe fısıldadı.', 'notes': 'no secrets: hiç sırrı olmamak.'}, {'id': 492, 'text': '"Dear Cecil! I have no secrets from you," she replied, smiling softly into his handsome face.', 'translation': '"Sevgili Cecil! Senden hiçbir sırrım yok ki benim," diye yanıtladı, onun yakışıklı yüzüne usulca gülümseyerek.', 'notes': 'smiling softly: usulca gülümseyen.'}, {'id': 493, 'text': '"Yes, you have," he answered playfully; "you have never told me what happened when you were locked up with the ghost."', 'translation': '"Evet var," diye neşeyle yanıtladı adam; "hayaletle baş başa kilitli kaldığında neler olduğunu bana hiç anlatmadın."', 'notes': 'locked up with ghost: hayaletle kilitli kalan.'}, {'id': 494, 'text': '"I have never told anyone, Cecil," said Virginia gravely, her azure eyes turning toward the distant horizon.', 'translation': '"Bunu hiç kimseye anlatmadım Cecil," dedi Virginia ciddiyetle, gök mavisi gözlerini uzak ufka çevirerek.', 'notes': 'azure eyes: gök mavisi gözler.'}, {'id': 495, 'text': '"I know that, but surely you might tell me your husband?"', 'translation': '"Bunu biliyorum fakat kocana anlatabilirsin herhalde, değil mi?"', 'notes': 'might tell me: bana anlatabilirsin.'}, {'id': 496, 'text': '"Please do not ask me, Cecil," she pleaded earnestly; "I cannot tell anyone."', 'translation': '"Lütfen benden bunu isteme Cecil," diye içtenlikle yalvardı; "hiç kimseye anlatamam."', 'notes': 'pleaded earnestly: içtenlikle yalvardı.'}, {'id': 497, 'text': '"Poor Sir Simon! I owe him a very great debt indeed, one that I can never repay in mortal coin."', 'translation': '"Zavallı Sir Simon! Ona gerçekten çok büyük bir borcum var, fani paralarla asla ödeyemeyeceğim bir borç."', 'notes': 'mortal coin: fani para/dünyevi bedel.'}, {'id': 498, 'text': '"He made me see what Life is, and what Death signifies, and why Love is stronger than both."', 'translation': '"O bana Yaşam\'ın ne olduğunu, Ölüm\'ün ne anlama geldiğini ve Sevgi\'nin neden her ikisinden de güçlü olduğunu gösterdi."', 'notes': 'Love is stronger: Sevgi daha güçlüdür.'}, {'id': 499, 'text': 'The young Duke bent down and kissed his wife reverently upon her brow under the flowering almond branches.', 'translation': 'Genç Dük eğildi ve çiçek açan badem dallarının altında karısını alnından hürmetle öptü.', 'notes': 'kissed reverently: hürmetle öptü.'}, {'id': 500, 'text': '"You may keep your secret, my darling," he whispered softly, "so long as I have your eternal love."', 'translation': '"Sırrını kendine saklayabilirsin sevgilim," diye usulca fısıldadı adam, "yeter ki senin ebedi sevgin benimle olsun."', 'notes': 'eternal love: ebedi sevgi.'}]}]
